// 项目实战“复刻面试自习室”第 16 关：AI 流式输出、思考面板与超时兜底。
import type {AiLevel} from '../journey';

export const pjStream:AiLevel={id:'pj-stream',title:'AI 流式输出与思考面板',summary:'把等整段回答改成实时打字机流式输出：用 SSE 与 NDJSON 传输增量事件、按分片安全拆分 <think> 思考过程，并在前端中断、服务端超时心跳与模型降级下稳妥兜底',lessons:[
  {title:'这一关做什么：把等 30 秒变成打字机流式输出',body:'第 14 关的 AI 评分和第 15 关的 AI 老师多轮对话都已经跑通，但它们都有一个共同缺点：后端要等大模型把整段话全部生成完，才一次性返回 JSON。遇到复杂题，推理模型经常要想 20 到 30 秒，用户只能盯着加载提示干等，中间网关或浏览器还可能先超时断连。\n这一关把第 15 关的 AI 老师对话升级成完整的流式架构：\n一、流式传输：向大模型传 stream: true 读取上游 SSE，后端每收到一小段就立刻用 NDJSON 推给前端，首字时间降到 1 秒内；\n二、思考分离：把推理模型的 <think>…</think> 或 reasoning_content 拆成独立的思考事件，前端放进可折叠面板，不混进正式回答，也不存进多轮历史；\n三、随时停止：前端用 AbortController 一键中断生成，后端感知断连后立刻取消上游请求，没输出过内容就退回次数；\n四、超时与降级兜底：设好首字超时、空闲看门狗、总时长截止和保活心跳，主模型半路卡死或报错时先发 reset 清空残缺内容，再无缝切换到备用模型。'},
  {title:'SSE 与 NDJSON：两种流式协议怎么选',body:'做流式接口时，上游大模型和我们自己的前后端通常会用到两种协议：\n一、SSE（Server-Sent Events）：Content-Type 是 text/event-stream，每条消息写成 data: {...} 加空行，结尾通常是 data: [DONE]。OpenAI、DeepSeek 等绝大多数大模型接口都用这种格式；\n二、NDJSON（Newline-Delimited JSON）：Content-Type 是 application/x-ndjson，每行就是一个完整 JSON，靠换行符 \\n 分隔。\n为什么我们的 /api/chats/stream 返回给前端时选 NDJSON，而不是直接让浏览器用原生的 EventSource 连 SSE？\n因为浏览器原生 EventSource 只支持 GET 请求，没法在请求体里带 JSON（对话编号、题目编号、长消息），也不好自定义请求头。既然前端本来就要用 fetch 加 ReadableStream 自己读流，那逐行 split("\\n") 再 JSON.parse 的 NDJSON 反而最简洁，而且更容易统一表示 start、think、delta、reset、ping、done、error 等事件。\n还要注意加上两个防缓冲响应头：Cache-Control: no-store, no-transform 防止压缩代理攒包，X-Accel-Buffering: no 告诉 Nginx 等网关立刻把每一行推出去。',code:`# 上游大模型返回（SSE：data: 前缀 + 空行分隔）
data: {"choices":[{"delta":{"reasoning_content":"先梳理作用域"}}]}

data: {"choices":[{"delta":{"content":"defer 在函数返回前执行。"}}]}

data: [DONE]

# 我们的后端返回给前端（NDJSON：每行一个独立 JSON 事件）
{"t":"start"}
{"t":"think","text":"先梳理作用域"}
{"t":"delta","text":"defer 在函数返回前执行。"}
{"t":"done","chatId":7,"model":"deepseek-chat","remaining":19}`,explain:[{at:'data: {"choices":[{"delta":{"reasoning_content":"先梳理作用域"}}]}',text:'上游 SSE 的思考增量块：部分模型（如 DeepSeek 推理模式）把思考放在 delta.reasoning_content 里，每条消息以 data: 开头、空行结尾。'},{at:'data: {"choices":[{"delta":{"content":"defer 在函数返回前执行。"}}]}',text:'上游 SSE 的正文增量块：模型每吐出一两个词，就会推来一个这样的 delta.content。'},{at:'data: [DONE]',text:'OpenAI 兼容格式的结束标志，看到这一行就知道上游已经说完了。'},{at:'{"t":"start"}',text:'我们后端推给前端的 NDJSON 第一行：告诉前端连接已建立、流式输出开始。'},{at:'{"t":"think","text":"先梳理作用域"}',to:'{"t":"delta","text":"defer 在函数返回前执行。"}',text:'把思考内容和正式回答拆成 t 为 think 和 delta 的两类行事件，前端各自更新不同区域。'},{at:'{"t":"done","chatId":7,"model":"deepseek-chat","remaining":19}',text:'全部完成后发送 done 事件，顺便把新对话编号、实际使用的模型和今日剩余次数带回给前端。'}]},
  {title:'把 <think> 思考和正式回答拆开',body:'除了独立字段 reasoning_content，很多模型（或微调后的开源模型）会直接把思考过程包在正文开头的 <think>…</think> 标签里。\n新手最容易踩的坑是直接按片判断 chunk.includes("<think>")。真实网络里，TCP 和 SSE 分片不会挑在标签边界切开：第一块结尾可能是 "<thi"，第二块开头是 "nk>先看定义"；思考快结束时第一块结尾是 "结论如下</th"，第二块开头是 "ink>正文"。直接判断不仅会漏掉标签，还会把 "</th" 留在思考面板、把 "ink>" 漏进正文里。\n解决办法是用一个带最小尾部缓冲的三态解析器：\n一、init（初始态）：忽略开头空白，只要缓冲还是 "<think>" 的前缀（比如 "<"、"<th"）就先等下一片；凑满 "<think>" 就剥掉标签进入 think；一旦确定不是（比如直接来了 "这道题"），立刻切到 answer 并吐出缓冲，普通模型首字零延迟；\n二、think（思考态）：先找完整的 "</think>"；没找到时查找最后一个 "<" 字符（ASCII 字节，在 UTF-8 里也绝对不会把多字节汉字切坏），若从它开始到末尾正是 "</think>" 的前缀（如 "</"、"</th"），只把这几字节留在缓冲里，前面已确认的思考立刻回调吐出；\n三、answer（正文态）：之后所有分片直接透传。流结束调用 flush() 把缓冲里残余内容吐净，注意只把正式回答存进 chat_messages 表，不把思考过程存进去，免得第 15 关带历史追问时白白多传 token。',code:`function createThinkSplitter(onThink, onAnswer) {
  let mode = "init";
  let buf = "";

  function flushThink() {
    while (mode === "think") {
      const closeIdx = buf.indexOf("</think>");
      if (closeIdx >= 0) {
        if (closeIdx > 0) onThink(buf.slice(0, closeIdx));
        buf = buf.slice(closeIdx + 8);
        mode = "answer";
        if (buf) { onAnswer(buf); buf = ""; }
        return;
      }
      const lastLT = buf.lastIndexOf("<");
      if (lastLT >= 0 && "</think>".startsWith(buf.slice(lastLT))) {
        if (lastLT > 0) onThink(buf.slice(0, lastLT));
        buf = buf.slice(lastLT);
        return;
      }
      if (buf) { onThink(buf); buf = ""; }
      return;
    }
  }

  return {
    feedChunk(chunk) {
      if (!chunk) return;
      if (mode === "answer") { onAnswer(chunk); return; }
      buf += chunk;
      if (mode === "init") {
        const trimmed = buf.trimStart();
        if (!trimmed) return;
        if (trimmed.startsWith("<think>")) {
          buf = trimmed.slice(7);
          mode = "think";
        } else if ("<think>".startsWith(trimmed)) {
          return;
        } else {
          mode = "answer";
          onAnswer(buf);
          buf = "";
          return;
        }
      }
      flushThink();
    },
    flush() {
      if (!buf) return;
      if (mode === "think") onThink(buf);
      else onAnswer(buf);
      buf = "";
    },
  };
}`,explain:[{at:'function createThinkSplitter(onThink, onAnswer) {',to:'let buf = "";',text:'创建流式拆分器：mode 记录当前处于 init、think 还是 answer；buf 暂存尚未确认归属的边界字符。'},{at:'function flushThink() {',to:'while (mode === "think") {',text:'只在思考阶段反复消费缓冲区里的内容。'},{at:'const closeIdx = buf.indexOf("</think>");',to:'return;',text:'如果已经凑出完整的 </think>，把标签前面的思考交给 onThink，切到 answer 状态，再把标签后面的残余正文直接交给 onAnswer。'},{at:'const lastLT = buf.lastIndexOf("<");',to:'return;',text:'没找到结束标签时，查看最后一个 <。如果从它到末尾正好是 </think> 的前缀（例如 </th），只把这段尾巴留在 buf 里等下一片，它前面已确认安全的思考文字立刻推送出去。'},{at:'if (buf) { onThink(buf); buf = ""; }',to:'return;',text:'尾巴也不是 </think> 的前缀（比如普通内容或 <b>），整块都是安全思考文本，直接推走并清空缓冲。'},{at:'return {',to:'buf += chunk;',text:'返回拆分器对象：已经进入 answer 阶段后不再缓冲，直接透传；否则先拼到 buf。'},{at:'if (mode === "init") {',to:'if (!trimmed) return;',text:'开流前先去掉前导空白；如果全是空白就再等下一片。'},{at:'if (trimmed.startsWith("<think>")) {',to:'mode = "think";',text:'确认以 <think> 开头：剥掉标签并切入思考态，接着下面 flushThink 会立刻处理同行后半截。'},{at:'} else if ("<think>".startsWith(trimmed)) {',to:'return;',text:'缓冲还是 <think> 的前缀（例如 "<t"），先等等下一片再判断。'},{at:'} else {',to:'flushThink();',text:'确定不是 <think> 开头，直接转入正文态并把当前缓冲立刻推给 onAnswer，不让首字白白卡住。'},{at:'flush() {',to:'buf = "";',text:'上游流结束时调用：如果还剩一点没闭合成标签的字符，按当前状态回调出去，绝不丢尾巴。'}]},
  {title:'超时兜底、心跳与模型降级',body:'在流式场景里，只靠第 14 关的“总超时 30 秒”远远不够：\n一、首字超时（firstTimeoutMs，如 15 秒）：连上上游后迟迟不吐第一个字，说明对方队列堵死，15 秒直接放弃并切换，不能让用户干等一分钟；\n二、空闲看门狗（idleTimeoutMs，如 20 秒）：上游吐了几个字之后半路卡住不动，总时长还没到但连接其实已经死锁。每次收到一块思考或正文就“喂狗”重置计时器，超过 20 秒没新动静立刻掐断；\n三、硬截止总超时（timeoutMs，如 60 秒）：限制整条流的最长生命周期，防止慢流无限占用服务端连接；\n四、保活心跳（ping）：模型深度思考时可能好几秒不吐字，网关和浏览器容易主动断线。后端定时每隔 10 秒写一行 {"t":"ping"}，前端收到直接忽略即可保活。\n最后是模型降级：配置备用模型 AI_FALLBACK_MODEL。主模型遇到 429/500、首字超时或空闲超时时：\n- 如果还没向前端输出任何内容，直接静默换备用模型重试；\n- 如果已经吐出了半截内容才卡死，必须先发一行 {"t":"reset"} 让前端清空残缺文本，再切备用模型从头输出。\n只有所有候选模型都失败时才发 {"t":"error"} 并退回提问次数；前端主动断开且尚未输出时也要退回次数。'},
  {title:'流式接口约定',body:'流式对话统一用 POST /api/chats/stream（不传 chatId 是新开对话，传了则接着追问）。参数错误、未登录、对话不存在、次数用完、未配置密钥都在开始流式响应前用标准状态码返回 JSON；一旦开始推流（200），后续异常改由 NDJSON 的 error 事件告知。',code:`POST /api/chats/stream
请求头：Cookie: session=…   Content-Type: application/json
请求体：{"chatId": 7, "questionId": 1, "message": "defer 什么时候执行？"}

响应头（流式）：
Content-Type: application/x-ndjson; charset=utf-8
Cache-Control: no-store, no-transform
X-Accel-Buffering: no

响应体（逐行 NDJSON 事件）：
{"t":"start"}
{"t":"model","model":"primary-model"}
{"t":"think","text":"先回顾 defer 的压栈规则"}
{"t":"delta","text":"defer 在函数返回前执行"}
{"t":"ping"}
{"t":"reset"}
{"t":"model","model":"backup-model","fallback":true}
{"t":"done","chatId":7,"model":"backup-model","remaining":19}
{"t":"error","message":"AI 服务暂时不可用，请稍后再试"}

错误（开始流式输出前）：400 参数不对 · 401 未登录 · 404 对话或题目不存在 · 429 次数用完 · 503 未配置
环境变量：AI_FALLBACK_MODEL · AI_FIRST_TIMEOUT_MS=15000 · AI_IDLE_TIMEOUT_MS=20000 · AI_TIMEOUT_MS=60000`,explain:[{at:'POST /api/chats/stream',to:'请求体：{"chatId": 7, "questionId": 1, "message": "defer 什么时候执行？"}',text:'同一个流式接口同时支持开新对话和追问：不传 chatId 为新开，传了 chatId 为追问。'},{at:'响应头（流式）：',to:'X-Accel-Buffering: no',text:'声明 NDJSON 流式内容类型，并关闭网关和代理缓冲。'},{at:'响应体（逐行 NDJSON 事件）：',to:'{"t":"model","model":"primary-model"}',text:'先发 start，再告知当前尝试的主模型名称。'},{at:'{"t":"think","text":"先回顾 defer 的压栈规则"}',to:'{"t":"delta","text":"defer 在函数返回前执行"}',text:'思考增量和正文增量分开发，前端放进不同区域。'},{at:'{"t":"ping"}',text:'空闲等待期间的心跳保活行，前端忽略它。'},{at:'{"t":"reset"}',to:'{"t":"model","model":"backup-model","fallback":true}',text:'主模型半路失败时先让前端清空残缺内容，再宣告切换到备用模型。'},{at:'{"t":"done","chatId":7,"model":"backup-model","remaining":19}',text:'全部成功且已落库后发 done，带上 chatId、最终模型名和剩余次数。'},{at:'{"t":"error","message":"AI 服务暂时不可用，请稍后再试"}',text:'兜底模型也失败时发 error（此时后端已把次数退回）。'},{at:'错误（开始流式输出前）：',to:'环境变量：AI_FALLBACK_MODEL · AI_FIRST_TIMEOUT_MS=15000 · AI_IDLE_TIMEOUT_MS=20000 · AI_TIMEOUT_MS=60000',text:'开流前的校验照样用标准 HTTP 状态码；降级模型和三段超时均可通过环境变量配置，方便测试与上线调优。'}]},
  {title:'任务一：后端流式解析与兜底服务',body:'把第 15 关的大模型客户端扩展成支持流式请求：能边读上游 SSE 边拆分 <think>、能同时支持 reasoning_content，并具备首字超时、空闲看门狗、总时长截止与备用模型降级重试。',variants:{go:{practice:{steps:['新建 internal/ai/stream.go，补完 TODO 1 到 3。','运行 go build ./...，确认编译没有报错。'],expect:'go build ./... 没有输出'},code:'// internal/ai/stream.go\npackage ai\n\nimport (\n    "bufio"\n    "bytes"\n    "context"\n    "encoding/json"\n    "errors"\n    "fmt"\n    "net/http"\n    "os"\n    "strconv"\n    "strings"\n    "time"\n)\n\ntype StreamCallbacks struct {\n    OnModel func(model string, fallback bool)\n    OnThink func(text string)\n    OnDelta func(text string)\n    OnReset func()\n}\n\ntype ThinkSplitter struct {\n    mode     string\n    buf      string\n    onThink  func(string)\n    onAnswer func(string)\n}\n\nfunc NewThinkSplitter(onThink, onAnswer func(string)) *ThinkSplitter {\n    return &ThinkSplitter{mode: "init", onThink: onThink, onAnswer: onAnswer}\n}\n\nfunc (s *ThinkSplitter) FeedChunk(chunk string) {\n    // TODO 1：实现 init / think / answer 三态拆分，在 think 态用 strings.LastIndexByte(s.buf, \'<\') 保留 </think> 前缀尾巴\n}\n\nfunc (s *ThinkSplitter) Flush() {\n    if s.buf == "" {\n        return\n    }\n    if s.mode == "think" {\n        s.onThink(s.buf)\n    } else {\n        s.onAnswer(s.buf)\n    }\n    s.buf = ""\n}\n\nfunc envDurationMs(name string, defMs int) time.Duration {\n    if v, err := strconv.Atoi(os.Getenv(name)); err == nil && v > 0 {\n        return time.Duration(v) * time.Millisecond\n    }\n    return time.Duration(defMs) * time.Millisecond\n}\n\nfunc (c *Client) streamAttempt(ctx context.Context, model string, messages []Message, temperature float64, onThink, onDelta func(string)) (bool, error) {\n    // TODO 2：用 context.WithTimeout(ctx, total) 和 time.AfterFunc(first, cancelAttempt) 分别控制总超时、首字超时与空闲看门狗；\n    //         POST 到 /chat/completions 并带上 "stream": true（使用不设固定 Timeout 的 &http.Client{}）；\n    //         逐行读取 data: {...}，分别把 delta.ReasoningContent 交给 onThink、delta.Content 交给 ThinkSplitter.FeedChunk，\n    //         每次收到内容重置空闲看门狗；读到 data: [DONE] 时调用 splitter.Flush()\n    return false, nil\n}\n\n// StreamWithFallback 依次尝试主模型与备用模型，已输出过半截内容时先回调 OnReset 再切换。\nfunc (c *Client) StreamWithFallback(ctx context.Context, messages []Message, temperature float64, cb StreamCallbacks) (string, error) {\n    if c.apiKey == "" {\n        return "", ErrNotConfigured\n    }\n    // TODO 3：构造候选列表 [c.model]（若 AI_FALLBACK_MODEL 非空且不同于主模型则追加）；\n    //         循环尝试 streamAttempt：每次调用 cb.OnModel；若 ctx 已取消直接返回；\n    //         若失败且上一模型已输出内容（wrote == true），先调用 cb.OnReset() 再试备用模型\n    return "", errors.New("未实现")\n}',explain:[{at:'// internal/ai/stream.go',to:')',text:'在 ai 包新增 stream.go，和第 14 关的 client.go 共用同一个 Client 和 Message。'},{at:'type StreamCallbacks struct {',to:'}',text:'流式回调集合：通知当前切换到了哪个模型、收到思考块、收到正文块、以及降级前通知清空。'},{at:'type ThinkSplitter struct {',to:'func NewThinkSplitter(onThink, onAnswer func(string)) *ThinkSplitter {',text:'拆分器结构体：保存当前状态（init / think / answer）和未决缓冲 buf。'},{at:'return &ThinkSplitter{mode: "init", onThink: onThink, onAnswer: onAnswer}',text:'初始化为 init 状态。'},{at:'func (s *ThinkSplitter) FeedChunk(chunk string) {',to:'// TODO 1',text:'核心分片解析方法，要你补全。'},{at:'func (s *ThinkSplitter) Flush() {',to:'s.buf = ""',text:'流结束时把缓冲区里没组成完整标签的尾巴按当前状态吐出去。'},{at:'func envDurationMs(name string, defMs int) time.Duration {',to:'return time.Duration(defMs) * time.Millisecond',text:'从环境变量读取毫秒超时值，没设置或非法时回落到默认值。'},{at:'func (c *Client) streamAttempt(',to:'return false, nil',text:'单次流式请求与三段超时控制，要你补全。注意流式请求不能用带固定 Client.Timeout 的客户端，必须靠 context 控制超时。'},{at:'func (c *Client) StreamWithFallback(',to:'return "", errors.New("未实现")',text:'主备模型降级循环，要你补全。'}],solution:{code:'// internal/ai/stream.go\npackage ai\n\nimport (\n    "bufio"\n    "bytes"\n    "context"\n    "encoding/json"\n    "errors"\n    "fmt"\n    "net/http"\n    "os"\n    "strconv"\n    "strings"\n    "time"\n)\n\ntype StreamCallbacks struct {\n    OnModel func(model string, fallback bool)\n    OnThink func(text string)\n    OnDelta func(text string)\n    OnReset func()\n}\n\ntype ThinkSplitter struct {\n    mode     string\n    buf      string\n    onThink  func(string)\n    onAnswer func(string)\n}\n\nfunc NewThinkSplitter(onThink, onAnswer func(string)) *ThinkSplitter {\n    return &ThinkSplitter{mode: "init", onThink: onThink, onAnswer: onAnswer}\n}\n\nfunc (s *ThinkSplitter) FeedChunk(chunk string) {\n    if chunk == "" {\n        return\n    }\n    if s.mode == "answer" {\n        s.onAnswer(chunk)\n        return\n    }\n    s.buf += chunk\n    if s.mode == "init" {\n        trimmed := strings.TrimLeft(s.buf, " \\t\\r\\n")\n        if trimmed == "" {\n            return\n        }\n        if strings.HasPrefix(trimmed, "<think>") {\n            s.buf = trimmed[len("<think>"):]\n            s.mode = "think"\n        } else if strings.HasPrefix("<think>", trimmed) {\n            return\n        } else {\n            s.mode = "answer"\n            s.onAnswer(s.buf)\n            s.buf = ""\n            return\n        }\n    }\n    for s.mode == "think" {\n        if idx := strings.Index(s.buf, "</think>"); idx >= 0 {\n            if idx > 0 {\n                s.onThink(s.buf[:idx])\n            }\n            rest := s.buf[idx+len("</think>"):]\n            s.buf = ""\n            s.mode = "answer"\n            if rest != "" {\n                s.onAnswer(rest)\n            }\n            return\n        }\n        lastLT := strings.LastIndexByte(s.buf, \'<\')\n        if lastLT >= 0 && strings.HasPrefix("</think>", s.buf[lastLT:]) {\n            if lastLT > 0 {\n                s.onThink(s.buf[:lastLT])\n            }\n            s.buf = s.buf[lastLT:]\n            return\n        }\n        if s.buf != "" {\n            s.onThink(s.buf)\n            s.buf = ""\n        }\n        return\n    }\n}\n\nfunc (s *ThinkSplitter) Flush() {\n    if s.buf == "" {\n        return\n    }\n    if s.mode == "think" {\n        s.onThink(s.buf)\n    } else {\n        s.onAnswer(s.buf)\n    }\n    s.buf = ""\n}\n\nfunc envDurationMs(name string, defMs int) time.Duration {\n    if v, err := strconv.Atoi(os.Getenv(name)); err == nil && v > 0 {\n        return time.Duration(v) * time.Millisecond\n    }\n    return time.Duration(defMs) * time.Millisecond\n}\n\nfunc (c *Client) streamAttempt(ctx context.Context, model string, messages []Message, temperature float64, onThink, onDelta func(string)) (bool, error) {\n    firstTimeout := envDurationMs("AI_FIRST_TIMEOUT_MS", 15000)\n    idleTimeout := envDurationMs("AI_IDLE_TIMEOUT_MS", 20000)\n    totalTimeout := envDurationMs("AI_TIMEOUT_MS", 60000)\n    totalCtx, totalCancel := context.WithTimeout(ctx, totalTimeout)\n    defer totalCancel()\n    attemptCtx, cancelAttempt := context.WithCancel(totalCtx)\n    defer cancelAttempt()\n    watchdog := time.AfterFunc(firstTimeout, cancelAttempt)\n    defer watchdog.Stop()\n\n    body, err := json.Marshal(map[string]any{"model": model, "temperature": temperature, "messages": messages, "stream": true})\n    if err != nil {\n        return false, err\n    }\n    req, err := http.NewRequestWithContext(attemptCtx, http.MethodPost, c.baseURL+"/chat/completions", bytes.NewReader(body))\n    if err != nil {\n        return false, err\n    }\n    req.Header.Set("Authorization", "Bearer "+c.apiKey)\n    req.Header.Set("Content-Type", "application/json")\n    streamClient := &http.Client{}\n    resp, err := streamClient.Do(req)\n    if err != nil {\n        return false, err\n    }\n    defer resp.Body.Close()\n    if resp.StatusCode != http.StatusOK {\n        return false, fmt.Errorf("AI 服务返回状态码 %d", resp.StatusCode)\n    }\n\n    wrote := false\n    splitter := NewThinkSplitter(func(t string) {\n        wrote = true\n        onThink(t)\n    }, func(t string) {\n        wrote = true\n        onDelta(t)\n    })\n    scanner := bufio.NewScanner(resp.Body)\n    scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)\n    for scanner.Scan() {\n        line := strings.TrimSpace(scanner.Text())\n        if !strings.HasPrefix(line, "data:") {\n            continue\n        }\n        payload := strings.TrimSpace(strings.TrimPrefix(line, "data:"))\n        if payload == "[DONE]" {\n            splitter.Flush()\n            return wrote, nil\n        }\n        var chunk struct {\n            Choices []struct {\n                Delta struct {\n                    Content          string `json:"content"`\n                    ReasoningContent string `json:"reasoning_content"`\n                } `json:"delta"`\n            } `json:"choices"`\n        }\n        if err := json.Unmarshal([]byte(payload), &chunk); err != nil || len(chunk.Choices) == 0 {\n            continue\n        }\n        watchdog.Reset(idleTimeout)\n        delta := chunk.Choices[0].Delta\n        if delta.ReasoningContent != "" {\n            wrote = true\n            onThink(delta.ReasoningContent)\n        }\n        if delta.Content != "" {\n            splitter.FeedChunk(delta.Content)\n        }\n    }\n    if err := scanner.Err(); err != nil {\n        return wrote, err\n    }\n    if attemptCtx.Err() != nil {\n        return wrote, attemptCtx.Err()\n    }\n    splitter.Flush()\n    return wrote, nil\n}\n\n// StreamWithFallback 依次尝试主模型与备用模型，已输出过半截内容时先回调 OnReset 再切换。\nfunc (c *Client) StreamWithFallback(ctx context.Context, messages []Message, temperature float64, cb StreamCallbacks) (string, error) {\n    if c.apiKey == "" {\n        return "", ErrNotConfigured\n    }\n    candidates := []string{c.model}\n    if fb := strings.TrimSpace(os.Getenv("AI_FALLBACK_MODEL")); fb != "" && fb != c.model {\n        candidates = append(candidates, fb)\n    }\n    var lastErr error\n    for i, model := range candidates {\n        if ctx.Err() != nil {\n            return "", ctx.Err()\n        }\n        cb.OnModel(model, i > 0)\n        wrote, err := c.streamAttempt(ctx, model, messages, temperature, cb.OnThink, cb.OnDelta)\n        if err == nil {\n            return model, nil\n        }\n        lastErr = err\n        if ctx.Err() != nil {\n            return "", ctx.Err()\n        }\n        if wrote && i+1 < len(candidates) {\n            cb.OnReset()\n        }\n    }\n    return "", lastErr\n}',explain:[{at:'// internal/ai/stream.go',to:')',text:'在 ai 包新增 stream.go，和第 14 关的 client.go 共用同一个 Client 和 Message。'},{at:'type StreamCallbacks struct {',to:'}',text:'流式回调集合：通知模型切换、思考增量、正文增量和重置清空。'},{at:'type ThinkSplitter struct {',to:'return &ThinkSplitter{mode: "init", onThink: onThink, onAnswer: onAnswer}',text:'拆分器结构体及构造器，从 init 状态起步。'},{at:'func (s *ThinkSplitter) FeedChunk(chunk string) {',to:'s.buf += chunk',text:'answer 态零缓冲直接透传；否则先追加到缓冲。'},{at:'if s.mode == "init" {',to:'s.mode = "think"',text:'init 态检查开头空白后是不是 <think>：匹配则剥掉标签切入 think 态。'},{at:'} else if strings.HasPrefix("<think>", trimmed) {',to:'return',text:'缓冲还是 <think> 的前缀就先等下一片。'},{at:'} else {',to:'return',text:'确定不是思考标签时，立刻切到 answer 态并吐出缓冲。'},{at:'for s.mode == "think" {',to:'return',text:'think 态先找完整的 </think>；找到就把前半段思考吐出并切进 answer 透传剩余正文。'},{at:'lastLT := strings.LastIndexByte',to:'return',text:'没找到结束标签时用 LastIndexByte 定位最后一个单字节 <，只留可能是 </think> 前缀的尾巴，绝不会把多字节汉字切坏。'},{at:'if s.buf != "" {',to:'return',text:'尾巴也不是 </think> 前缀时，把当前缓冲全部作为已确认的思考吐出。'},{at:'func (s *ThinkSplitter) Flush() {',to:'s.buf = ""',text:'流结束把剩余缓冲按当前状态吐出。'},{at:'func envDurationMs(name string, defMs int) time.Duration {',to:'return time.Duration(defMs) * time.Millisecond',text:'从环境变量读取毫秒超时。'},{at:'func (c *Client) streamAttempt(',to:'defer watchdog.Stop()',text:'三段超时控制：外层 totalCtx 是硬截止总时长，内层 attemptCtx 挂在 time.AfterFunc 看门狗上，先按首字超时启动。'},{at:'body, err := json.Marshal(',to:'streamClient := &http.Client{}',text:'带 stream: true 发起请求；注意新建不设固定 Timeout 的 http.Client，否则会在读长流到一半时被硬切断。'},{at:'resp, err := streamClient.Do(req)',to:'return false, fmt.Errorf("AI 服务返回状态码 %d", resp.StatusCode)',text:'非 200 状态码立刻返回失败以便切换备用模型。'},{at:'wrote := false',to:'scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)',text:'记录是否已经向前端输出内容；调大 scanner 缓冲避免长行溢出。'},{at:'for scanner.Scan() {',to:'if payload == "[DONE]" {',text:'逐行解析 SSE 的 data: 行，读到 [DONE] 就收尾并结束。'},{at:'splitter.Flush()',to:'var chunk struct {',text:'遇到 [DONE] 时调用 Flush 吐净尾部字符，再定义结构解析增量 JSON。'},{at:'Choices []struct {',to:'continue',text:'解析 choices[0].delta 里的 content 与 reasoning_content，非法或心跳注释行跳过。'},{at:'watchdog.Reset(idleTimeout)',to:'splitter.FeedChunk(delta.Content)',text:'每收到有效增量立刻喂狗重置空闲超时，分别处理 reasoning_content 和带 <think> 标签的 content。'},{at:'if err := scanner.Err(); err != nil {',to:'return wrote, nil',text:'如果流中途因为超时或断网中断，检查 scanner 和 context 错误并返回。'},{at:'func (c *Client) StreamWithFallback(',to:'return "", lastErr',text:'先试主模型，若在客户端未取消的情况下超时或失败，当已写出半截内容时先回调 OnReset 再切到备用模型。'}]}},java:{practice:{steps:['新建 ai/ThinkSplitter.java 和 ai/AiStreamClient.java，补完 TODO 1 到 3。','在 application.properties 里加上 fallback 和超时配置。','运行 mvn test-compile 确认没有语法报错。'],expect:'BUILD SUCCESS'},code:'// ai/ThinkSplitter.java\npackage com.example.zixishi.ai;\n\nimport java.util.function.Consumer;\n\npublic class ThinkSplitter {\n    private enum Mode { INIT, THINK, ANSWER }\n    private Mode mode = Mode.INIT;\n    private final StringBuilder buf = new StringBuilder();\n    private final Consumer<String> onThink;\n    private final Consumer<String> onAnswer;\n\n    public ThinkSplitter(Consumer<String> onThink, Consumer<String> onAnswer) {\n        this.onThink = onThink;\n        this.onAnswer = onAnswer;\n    }\n\n    public void feedChunk(String chunk) {\n        // TODO 1：实现 init / think / answer 三态拆分；think 态用 buf.lastIndexOf("<") 保留可能是 </think> 前缀的尾巴\n    }\n\n    public void flush() {\n        if (buf.isEmpty()) return;\n        if (mode == Mode.THINK) onThink.accept(buf.toString());\n        else onAnswer.accept(buf.toString());\n        buf.setLength(0);\n    }\n}\n\n// ai/AiStreamClient.java\npackage com.example.zixishi.ai;\n\nimport com.fasterxml.jackson.databind.JsonNode;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport java.io.*;\nimport java.net.URI;\nimport java.net.http.*;\nimport java.nio.charset.StandardCharsets;\nimport java.time.Duration;\nimport java.util.*;\nimport java.util.concurrent.*;\nimport java.util.concurrent.atomic.*;\nimport java.util.function.BiConsumer;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.stereotype.Component;\n\n@Component\npublic class AiStreamClient {\n\n    public interface Callbacks {\n        void onModel(String model, boolean fallback);\n        void onThink(String text);\n        void onDelta(String text);\n        void onReset();\n    }\n\n    private final String baseUrl, apiKey, model, fallbackModel;\n    private final long firstMs, idleMs, totalMs;\n    private final ObjectMapper mapper;\n    private final HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();\n    private final ScheduledExecutorService timers = Executors.newScheduledThreadPool(2, r -> {\n        Thread t = new Thread(r, "ai-stream-watchdog");\n        t.setDaemon(true);\n        return t;\n    });\n\n    public AiStreamClient(@Value("${ai.base-url}") String baseUrl, @Value("${ai.api-key}") String apiKey,\n                          @Value("${ai.model}") String model, @Value("${ai.fallback-model:}") String fallbackModel,\n                          @Value("${ai.first-timeout-ms:15000}") long firstMs, @Value("${ai.idle-timeout-ms:20000}") long idleMs,\n                          @Value("${ai.timeout-ms:60000}") long totalMs, ObjectMapper mapper) {\n        this.baseUrl = baseUrl.replaceAll("/+$", "");\n        this.apiKey = apiKey;\n        this.model = model;\n        this.fallbackModel = fallbackModel == null ? "" : fallbackModel.strip();\n        this.firstMs = firstMs;\n        this.idleMs = idleMs;\n        this.totalMs = totalMs;\n        this.mapper = mapper;\n    }\n\n    private boolean streamAttempt(String modelName, List<AiClient.Message> messages, AtomicBoolean aborted,\n                                  AtomicReference<InputStream> activeBody, Callbacks cb) throws Exception {\n        // TODO 2：用 timers.schedule 控制总超时与首字/空闲看门狗（到期直接关闭 activeBody）；\n        //         POST /chat/completions（stream: true），逐行解析 SSE data: {...} 喂给 ThinkSplitter；\n        //         每收到一块数据就取消旧看门狗并重新定时 idleMs；读到 [DONE] 调用 splitter.flush()\n        return false;\n    }\n\n    public String streamWithFallback(List<AiClient.Message> messages, AtomicBoolean aborted,\n                                     AtomicReference<InputStream> activeBody, Callbacks cb) throws Exception {\n        if (apiKey.isBlank()) throw new AiClient.NotConfiguredException();\n        // TODO 3：按 [model, fallbackModel] 顺序尝试 streamAttempt；客户端未中止且已写出内容时先调用 cb.onReset() 再降级\n        throw new IllegalStateException("未实现");\n    }\n}\n\n# application.properties（加上备用模型与超时配置）\nai.fallback-model=${AI_FALLBACK_MODEL:}\nai.first-timeout-ms=${AI_FIRST_TIMEOUT_MS:15000}\nai.idle-timeout-ms=${AI_IDLE_TIMEOUT_MS:20000}\nai.timeout-ms=${AI_TIMEOUT_MS:60000}',explain:[{at:'// ai/ThinkSplitter.java',to:'import java.util.function.Consumer;',text:'新建 ThinkSplitter，用枚举表示 INIT、THINK、ANSWER 三种状态。'},{at:'public class ThinkSplitter {',to:'this.onAnswer = onAnswer;',text:'构造函数接收思考和正文两个回调。'},{at:'public void feedChunk(String chunk) {',to:'// TODO 1',text:'核心分片解析，要你补全。'},{at:'public void flush() {',to:'buf.setLength(0);',text:'流结束把缓冲里剩余字符按当前状态送出并清空。'},{at:'// ai/AiStreamClient.java',to:'import org.springframework.stereotype.Component;',text:'流式客户端使用 JDK 自带的 java.net.http.HttpClient，支持按流逐行读取。'},{at:'@Component',to:'void onReset();',text:'通过 @Component 交给 Spring 管理；Callbacks 定义流式回调接口，对应 NDJSON 的几类事件。'},{at:'private final String baseUrl, apiKey, model, fallbackModel;',to:'});',text:'守护线程的定时器用来触发首字、空闲和总超时，不会阻止 JVM 正常退出。'},{at:'public AiStreamClient(',to:'this.mapper = mapper;',text:'从 application.properties 注入主备模型和三段毫秒超时。'},{at:'private boolean streamAttempt(',to:'return false;',text:'单次流式尝试与看门狗实现，要你补全。'},{at:'public String streamWithFallback(',to:'throw new IllegalStateException("未实现");',text:'主备切换与重置控制，要你补全。'},{at:'# application.properties',to:'ai.timeout-ms=${AI_TIMEOUT_MS:60000}',text:'把降级模型和三段超时配置接进环境变量，方便测试时调成几百毫秒。'}],solution:{code:'// ai/ThinkSplitter.java\npackage com.example.zixishi.ai;\n\nimport java.util.function.Consumer;\n\npublic class ThinkSplitter {\n    private enum Mode { INIT, THINK, ANSWER }\n    private Mode mode = Mode.INIT;\n    private final StringBuilder buf = new StringBuilder();\n    private final Consumer<String> onThink;\n    private final Consumer<String> onAnswer;\n\n    public ThinkSplitter(Consumer<String> onThink, Consumer<String> onAnswer) {\n        this.onThink = onThink;\n        this.onAnswer = onAnswer;\n    }\n\n    public void feedChunk(String chunk) {\n        if (chunk == null || chunk.isEmpty()) return;\n        if (mode == Mode.ANSWER) { onAnswer.accept(chunk); return; }\n        buf.append(chunk);\n        if (mode == Mode.INIT) {\n            String trimmed = buf.toString().stripLeading();\n            if (trimmed.isEmpty()) return;\n            if (trimmed.startsWith("<think>")) {\n                buf.setLength(0);\n                buf.append(trimmed.substring(7));\n                mode = Mode.THINK;\n            } else if ("<think>".startsWith(trimmed)) {\n                return;\n            } else {\n                mode = Mode.ANSWER;\n                onAnswer.accept(buf.toString());\n                buf.setLength(0);\n                return;\n            }\n        }\n        while (mode == Mode.THINK) {\n            int closeIdx = buf.indexOf("</think>");\n            if (closeIdx >= 0) {\n                if (closeIdx > 0) onThink.accept(buf.substring(0, closeIdx));\n                String rest = buf.substring(closeIdx + 8);\n                buf.setLength(0);\n                mode = Mode.ANSWER;\n                if (!rest.isEmpty()) onAnswer.accept(rest);\n                return;\n            }\n            int lastLT = buf.lastIndexOf("<");\n            if (lastLT >= 0 && "</think>".startsWith(buf.substring(lastLT))) {\n                if (lastLT > 0) onThink.accept(buf.substring(0, lastLT));\n                String tail = buf.substring(lastLT);\n                buf.setLength(0);\n                buf.append(tail);\n                return;\n            }\n            if (!buf.isEmpty()) { onThink.accept(buf.toString()); buf.setLength(0); }\n            return;\n        }\n    }\n\n    public void flush() {\n        if (buf.isEmpty()) return;\n        if (mode == Mode.THINK) onThink.accept(buf.toString());\n        else onAnswer.accept(buf.toString());\n        buf.setLength(0);\n    }\n}\n\n// ai/AiStreamClient.java\npackage com.example.zixishi.ai;\n\nimport com.fasterxml.jackson.databind.JsonNode;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport java.io.*;\nimport java.net.URI;\nimport java.net.http.*;\nimport java.nio.charset.StandardCharsets;\nimport java.time.Duration;\nimport java.util.*;\nimport java.util.concurrent.*;\nimport java.util.concurrent.atomic.*;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.stereotype.Component;\n\n@Component\npublic class AiStreamClient {\n\n    public interface Callbacks {\n        void onModel(String model, boolean fallback);\n        void onThink(String text);\n        void onDelta(String text);\n        void onReset();\n    }\n\n    private final String baseUrl, apiKey, model, fallbackModel;\n    private final long firstMs, idleMs, totalMs;\n    private final ObjectMapper mapper;\n    private final HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();\n    private final ScheduledExecutorService timers = Executors.newScheduledThreadPool(2, r -> {\n        Thread t = new Thread(r, "ai-stream-watchdog");\n        t.setDaemon(true);\n        return t;\n    });\n\n    public AiStreamClient(@Value("${ai.base-url}") String baseUrl, @Value("${ai.api-key}") String apiKey,\n                          @Value("${ai.model}") String model, @Value("${ai.fallback-model:}") String fallbackModel,\n                          @Value("${ai.first-timeout-ms:15000}") long firstMs, @Value("${ai.idle-timeout-ms:20000}") long idleMs,\n                          @Value("${ai.timeout-ms:60000}") long totalMs, ObjectMapper mapper) {\n        this.baseUrl = baseUrl.replaceAll("/+$", "");\n        this.apiKey = apiKey;\n        this.model = model;\n        this.fallbackModel = fallbackModel == null ? "" : fallbackModel.strip();\n        this.firstMs = firstMs;\n        this.idleMs = idleMs;\n        this.totalMs = totalMs;\n        this.mapper = mapper;\n    }\n\n    private static void closeQuietly(InputStream in) {\n        if (in != null) try { in.close(); } catch (IOException ignored) {}\n    }\n\n    private boolean streamAttempt(String modelName, List<AiClient.Message> messages, AtomicBoolean aborted,\n                                  AtomicReference<InputStream> activeBody, Callbacks cb) throws Exception {\n        AtomicBoolean wrote = new AtomicBoolean(false);\n        AtomicBoolean timedOut = new AtomicBoolean(false);\n        String jsonBody = mapper.writeValueAsString(Map.of("model", modelName, "temperature", 0.5, "messages", messages, "stream", true));\n        HttpRequest req = HttpRequest.newBuilder().uri(URI.create(baseUrl + "/chat/completions"))\n            .header("Authorization", "Bearer " + apiKey).header("Content-Type", "application/json")\n            .timeout(Duration.ofMillis(totalMs))\n            .POST(HttpRequest.BodyPublishers.ofString(jsonBody, StandardCharsets.UTF_8)).build();\n        HttpResponse<InputStream> resp = client.send(req, HttpResponse.BodyHandlers.ofInputStream());\n        InputStream body = resp.body();\n        activeBody.set(body);\n        if (resp.statusCode() != 200) {\n            closeQuietly(body);\n            throw new IllegalStateException("AI 服务返回状态码 " + resp.statusCode());\n        }\n        Runnable kill = () -> { timedOut.set(true); closeQuietly(body); };\n        ScheduledFuture<?> totalTask = timers.schedule(kill, totalMs, TimeUnit.MILLISECONDS);\n        AtomicReference<ScheduledFuture<?>> idleTask = new AtomicReference<>(timers.schedule(kill, firstMs, TimeUnit.MILLISECONDS));\n        ThinkSplitter splitter = new ThinkSplitter(t -> { wrote.set(true); cb.onThink(t); }, t -> { wrote.set(true); cb.onDelta(t); });\n        try (BufferedReader reader = new BufferedReader(new InputStreamReader(body, StandardCharsets.UTF_8))) {\n            String line;\n            while (!aborted.get() && (line = reader.readLine()) != null) {\n                String trimmed = line.trim();\n                if (!trimmed.startsWith("data:")) continue;\n                String payload = trimmed.substring(5).trim();\n                if ("[DONE]".equals(payload)) { splitter.flush(); return wrote.get(); }\n                JsonNode root = mapper.readTree(payload);\n                JsonNode delta = root.path("choices").path(0).path("delta");\n                if (delta.isMissingNode()) continue;\n                idleTask.getAndSet(timers.schedule(kill, idleMs, TimeUnit.MILLISECONDS)).cancel(false);\n                String rc = delta.path("reasoning_content").asText("");\n                if (!rc.isEmpty()) { wrote.set(true); cb.onThink(rc); }\n                String ct = delta.path("content").asText("");\n                if (!ct.isEmpty()) splitter.feedChunk(ct);\n            }\n            if (timedOut.get()) throw new IOException("流式等待超时");\n            if (!aborted.get()) splitter.flush();\n            return wrote.get();\n        } finally {\n            totalTask.cancel(false);\n            idleTask.get().cancel(false);\n            activeBody.compareAndSet(body, null);\n            closeQuietly(body);\n        }\n    }\n\n    public String streamWithFallback(List<AiClient.Message> messages, AtomicBoolean aborted,\n                                     AtomicReference<InputStream> activeBody, Callbacks cb) throws Exception {\n        if (apiKey.isBlank()) throw new AiClient.NotConfiguredException();\n        List<String> candidates = new ArrayList<>();\n        candidates.add(model);\n        if (!fallbackModel.isEmpty() && !fallbackModel.equals(model)) candidates.add(fallbackModel);\n        Exception last = null;\n        for (int i = 0; i < candidates.size(); i++) {\n            if (aborted.get()) throw new CancellationException();\n            String m = candidates.get(i);\n            cb.onModel(m, i > 0);\n            try {\n                streamAttempt(m, messages, aborted, activeBody, cb);\n                if (aborted.get()) throw new CancellationException();\n                return m;\n            } catch (Exception e) {\n                last = e;\n                if (aborted.get()) throw e;\n                if (i + 1 < candidates.size()) cb.onReset();\n            }\n        }\n        throw last;\n    }\n}\n\n# application.properties（加上备用模型与超时配置）\nai.fallback-model=${AI_FALLBACK_MODEL:}\nai.first-timeout-ms=${AI_FIRST_TIMEOUT_MS:15000}\nai.idle-timeout-ms=${AI_IDLE_TIMEOUT_MS:20000}\nai.timeout-ms=${AI_TIMEOUT_MS:60000}',explain:[{at:'// ai/ThinkSplitter.java',to:'this.onAnswer = onAnswer;',text:'拆分器初始化为 INIT 状态并保存两个输出回调。'},{at:'public void feedChunk(String chunk) {',to:'buf.append(chunk);',text:'进入 ANSWER 后不再缓冲直接透传；否则先追加进 buf。'},{at:'if (mode == Mode.INIT) {',to:'mode = Mode.THINK;',text:'INIT 状态：剥掉开头的 <think> 并切到 THINK。'},{at:'} else if ("<think>".startsWith(trimmed)) {',to:'return;',text:'如果缓冲还是 <think> 前缀就等下一片。'},{at:'} else {',to:'return;',text:'一旦确定不是思考标签，立刻切到 ANSWER 并发出缓冲。'},{at:'while (mode == Mode.THINK) {',to:'return;',text:'THINK 状态：找到 </think> 时吐出前半段并切回 ANSWER。'},{at:'int lastLT = buf.lastIndexOf("<");',to:'return;',text:'没找到结束标签时用 lastIndexOf("<") 保留可能是 </think> 前缀的尾巴。'},{at:'if (!buf.isEmpty())',to:'return;',text:'确定不是结束标签前缀时全部作为思考发出并清空。'},{at:'public void flush() {',to:'buf.setLength(0);',text:'流结束把剩余缓冲吐出。'},{at:'// ai/AiStreamClient.java',to:'this.mapper = mapper;',text:'通过构造函数读出模型名、备用模型和三段超时配置，并准备 Daemon 定时器线程池。'},{at:'private static void closeQuietly(InputStream in) {',to:'AtomicReference<InputStream> activeBody, Callbacks cb) throws Exception {',text:'关闭上游输入流：一旦关闭，正在阻塞读行的 readLine() 会立刻抛出 IOException 退出；streamAttempt 负责单次流式请求。'},{at:'AtomicBoolean wrote = new AtomicBoolean(false);',to:'throw new IllegalStateException("AI 服务返回状态码 " + resp.statusCode());',text:'带着 stream: true 发出请求并把流对象登记到 activeBody，非 200 状态码立刻关闭流并抛出异常触发降级。'},{at:'Runnable kill = () ->',to:'String line;',text:'启动总时长任务和首字看门狗；BufferedReader 按行读取 SSE 数据。'},{at:'while (!aborted.get()',to:'if (!ct.isEmpty()) splitter.feedChunk(ct);',text:'每读到有效 delta 就取消旧看门狗、按 idleMs 重新定时，并分别把 reasoning_content 和 content 送进思考或拆分器。'},{at:'if (timedOut.get())',to:'closeQuietly(body);',text:'finally 块负责清理所有定时任务并关闭上游流，防止线程或连接泄漏。'},{at:'public String streamWithFallback(',to:'throw last;',text:'按主备顺序循环尝试；注意只要不是客户端主动中断，发生异常准备换备用模型时先发一次 reset（或者在主模型写出后再重置）。'},{at:'# application.properties',to:'ai.timeout-ms=${AI_TIMEOUT_MS:60000}',text:'把备用模型与三段超时参数暴露成环境变量。'}]}},node:{practice:{steps:['新建 src/ai/stream.js，补完 TODO 1 到 3。','运行 node -e "require(\'./src/ai/stream\')" 确认没有语法错误。'],expect:'命令正常退出，无报错'},code:'// src/ai/stream.js\nconst { NotConfiguredError } = require("./client");\n\nconst BASE_URL = (process.env.AI_BASE_URL || "https://api.deepseek.com").replace(/\\/+$/, "");\nconst API_KEY = process.env.AI_API_KEY || "";\nconst MODEL = process.env.AI_MODEL || "deepseek-chat";\nconst FALLBACK_MODEL = (process.env.AI_FALLBACK_MODEL || "").trim();\nconst FIRST_MS = Number(process.env.AI_FIRST_TIMEOUT_MS) || 15000;\nconst IDLE_MS = Number(process.env.AI_IDLE_TIMEOUT_MS) || 20000;\nconst TOTAL_MS = Number(process.env.AI_TIMEOUT_MS) || 60000;\n\nfunction createThinkSplitter(onThink, onAnswer) {\n  let mode = "init";\n  let buf = "";\n  // TODO 1：返回 { feedChunk(chunk), flush() }，在 think 态用 buf.lastIndexOf("<") 保留 </think> 前缀尾巴\n  return { feedChunk() {}, flush() {} };\n}\n\nasync function streamAttempt(model, messages, signal, cb) {\n  // TODO 2：创建内层 AbortController（绑定外层 signal 中止），并用 setTimeout 设置 FIRST_MS / IDLE_MS / TOTAL_MS 看门狗；\n  //         fetch POST BASE_URL + "/chat/completions"（带 stream: true）；\n  //         用 res.body.getReader() + TextDecoder({ stream: true }) 按换行读 data: {...}，\n  //         解析 delta.reasoning_content 和 delta.content，每次收到块重置空闲看门狗\n  return false;\n}\n\n// 依次尝试主模型与备用模型；主模型已输出部分内容后失败时，先调用 cb.onReset() 再降级\nasync function streamWithFallback(messages, signal, cb) {\n  if (!API_KEY) throw new NotConfiguredError();\n  // TODO 3：组装候选模型 [MODEL, FALLBACK_MODEL]（去重非空），循环调用 streamAttempt；\n  //         外层 signal 已中止时直接抛错，否则 wrote 为 true 时先 cb.onReset() 再切下一候选\n  throw new Error("未实现");\n}\n\nmodule.exports = { createThinkSplitter, streamWithFallback };',explain:[{at:'// src/ai/stream.js',to:'const TOTAL_MS = Number(process.env.AI_TIMEOUT_MS) || 60000;',text:'读取上游配置、备用模型和三段超时毫秒数。'},{at:'function createThinkSplitter(onThink, onAnswer) {',to:'return { feedChunk() {}, flush() {} };',text:'三态拆分器骨架，要你补全。'},{at:'async function streamAttempt(model, messages, signal, cb) {',to:'return false;',text:'单次流式读取与三段超时控制，要你补全。'},{at:'async function streamWithFallback(messages, signal, cb) {',to:'throw new Error("未实现");',text:'主备降级循环，要你补全。'},{at:'module.exports = { createThinkSplitter, streamWithFallback };',text:'导出拆分器和兜底流式入口。'}],solution:{code:'// src/ai/stream.js\nconst { NotConfiguredError } = require("./client");\n\nconst BASE_URL = (process.env.AI_BASE_URL || "https://api.deepseek.com").replace(/\\/+$/, "");\nconst API_KEY = process.env.AI_API_KEY || "";\nconst MODEL = process.env.AI_MODEL || "deepseek-chat";\nconst FALLBACK_MODEL = (process.env.AI_FALLBACK_MODEL || "").trim();\nconst FIRST_MS = Number(process.env.AI_FIRST_TIMEOUT_MS) || 15000;\nconst IDLE_MS = Number(process.env.AI_IDLE_TIMEOUT_MS) || 20000;\nconst TOTAL_MS = Number(process.env.AI_TIMEOUT_MS) || 60000;\n\nfunction createThinkSplitter(onThink, onAnswer) {\n  let mode = "init";\n  let buf = "";\n  function flushThink() {\n    while (mode === "think") {\n      const closeIdx = buf.indexOf("</think>");\n      if (closeIdx >= 0) {\n        if (closeIdx > 0) onThink(buf.slice(0, closeIdx));\n        buf = buf.slice(closeIdx + 8);\n        mode = "answer";\n        if (buf) { onAnswer(buf); buf = ""; }\n        return;\n      }\n      const lastLT = buf.lastIndexOf("<");\n      if (lastLT >= 0 && "</think>".startsWith(buf.slice(lastLT))) {\n        if (lastLT > 0) onThink(buf.slice(0, lastLT));\n        buf = buf.slice(lastLT);\n        return;\n      }\n      if (buf) { onThink(buf); buf = ""; }\n      return;\n    }\n  }\n  return {\n    feedChunk(chunk) {\n      if (!chunk) return;\n      if (mode === "answer") { onAnswer(chunk); return; }\n      buf += chunk;\n      if (mode === "init") {\n        const trimmed = buf.trimStart();\n        if (!trimmed) return;\n        if (trimmed.startsWith("<think>")) {\n          buf = trimmed.slice(7);\n          mode = "think";\n        } else if ("<think>".startsWith(trimmed)) {\n          return;\n        } else {\n          mode = "answer";\n          onAnswer(buf); buf = "";\n          return;\n        }\n      }\n      flushThink();\n    },\n    flush() {\n      if (!buf) return;\n      if (mode === "think") onThink(buf); else onAnswer(buf);\n      buf = "";\n    },\n  };\n}\n\nasync function streamAttempt(model, messages, signal, cb) {\n  const ctl = new AbortController();\n  const onOuterAbort = () => ctl.abort();\n  if (signal?.aborted) ctl.abort(); else signal?.addEventListener("abort", onOuterAbort, { once: true });\n  let alive = false;\n  let timer = setTimeout(() => ctl.abort(new Error("first timeout")), FIRST_MS);\n  let idleTimer = null;\n  const touch = () => {\n    if (!alive) { alive = true; clearTimeout(timer); timer = setTimeout(() => ctl.abort(new Error("total timeout")), TOTAL_MS); }\n    if (idleTimer) clearTimeout(idleTimer);\n    idleTimer = setTimeout(() => ctl.abort(new Error("idle timeout")), IDLE_MS);\n  };\n  let wrote = false;\n  const splitter = createThinkSplitter((t) => { wrote = true; cb.onThink(t); }, (t) => { wrote = true; cb.onDelta(t); });\n  try {\n    const res = await fetch(`${BASE_URL}/chat/completions`, {\n      method: "POST",\n      headers: { Authorization: `Bearer ${API_KEY}`, "Content-Type": "application/json" },\n      body: JSON.stringify({ model, temperature: 0.5, messages, stream: true }),\n      signal: ctl.signal,\n    });\n    if (!res.ok) throw new Error(`AI 服务返回状态码 ${res.status}`);\n    const reader = res.body.getReader(), dec = new TextDecoder();\n    let buf = "";\n    while (true) {\n      const { done, value } = await reader.read();\n      if (done) break;\n      buf += dec.decode(value, { stream: true });\n      let i;\n      while ((i = buf.indexOf("\\n")) >= 0) {\n        const line = buf.slice(0, i).trim();\n        buf = buf.slice(i + 1);\n        if (!line.startsWith("data:")) continue;\n        const payload = line.slice(5).trim();\n        if (payload === "[DONE]") { splitter.flush(); return wrote; }\n        let data; try { data = JSON.parse(payload); } catch { continue; }\n        const delta = data.choices?.[0]?.delta;\n        if (!delta) continue;\n        touch();\n        if (delta.reasoning_content) { wrote = true; cb.onThink(delta.reasoning_content); }\n        if (delta.content) splitter.feedChunk(delta.content);\n      }\n    }\n    splitter.flush();\n    return wrote;\n  } catch (err) {\n    err.wrote = wrote;\n    throw err;\n  } finally {\n    clearTimeout(timer);\n    if (idleTimer) clearTimeout(idleTimer);\n    signal?.removeEventListener("abort", onOuterAbort);\n  }\n}\n\n// 依次尝试主模型与备用模型；主模型已输出部分内容后失败时，先调用 cb.onReset() 再降级\nasync function streamWithFallback(messages, signal, cb) {\n  if (!API_KEY) throw new NotConfiguredError();\n  const candidates = FALLBACK_MODEL && FALLBACK_MODEL !== MODEL ? [MODEL, FALLBACK_MODEL] : [MODEL];\n  let lastErr;\n  for (let i = 0; i < candidates.length; i++) {\n    if (signal?.aborted) throw lastErr || new DOMException("Aborted", "AbortError");\n    const model = candidates[i];\n    cb.onModel(model, i > 0);\n    try {\n      await streamAttempt(model, messages, signal, cb);\n      return model;\n    } catch (err) {\n      lastErr = err;\n      if (signal?.aborted) throw err;\n      if (err.wrote && i + 1 < candidates.length) cb.onReset();\n    }\n  }\n  throw lastErr;\n}\n\nmodule.exports = { createThinkSplitter, streamWithFallback };',explain:[{at:'// src/ai/stream.js',to:'const TOTAL_MS = Number(process.env.AI_TIMEOUT_MS) || 60000;',text:'读取地址、密钥、主备模型与三段超时毫秒数。'},{at:'function createThinkSplitter(onThink, onAnswer) {',to:'flushThink();',text:'和讲解卡片一样的三态拆分器：开流缓冲前缀、思考态保留 </think> 尾巴、正文态直接透传。'},{at:'flush() {',to:'buf = "";',text:'flush 在流结束时将残余缓冲按当前状态回调并清空。'},{at:'async function streamAttempt(model, messages, signal, cb) {',to:'if (signal?.aborted) ctl.abort();',text:'创建单次尝试专用的 AbortController，并联动外部请求中断信号。'},{at:'let alive = false;',to:'idleTimer = setTimeout(() => ctl.abort(new Error("idle timeout")), IDLE_MS);',text:'首字超时先倒计时；一旦收到第一块，换成 totalMs 硬截止，并每次增量重置 idleMs 看门狗。'},{at:'let wrote = false;',to:'if (!res.ok) throw new Error(',text:'发出 stream: true 请求，检查状态码。'},{at:'const reader = res.body.getReader()',to:'if (payload === "[DONE]")',text:'用 ReadableStream 边收边拆换行，解析每条 data: 行，读到 [DONE] 收尾返回。'},{at:'let data; try { data = JSON.parse(payload); } catch { continue; }',to:'if (delta.content) splitter.feedChunk(delta.content);',text:'解析增量 JSON，喂狗续命，分别把 reasoning_content 与 content 分发给思考回调或拆分器。'},{at:'splitter.flush();',to:'signal?.removeEventListener("abort", onOuterAbort);',text:'把 wrote 挂在异常上方便外层决定要不要发 reset，并在 finally 里释放所有定时器与监听。'},{at:'async function streamWithFallback(',to:'throw lastErr;',text:'依次尝试主备模型，客户端未中止且已经输出过内容时先发 reset 再降级。'},{at:'module.exports =',text:'导出拆分器和流式兜底函数。'}]}},python:{practice:{steps:['新建 app/ai_stream.py，补完 TODO 1 到 3。','运行 python -c "import app.ai_stream" 确认导入正常。'],expect:'命令正常退出，无报错'},code:'# app/ai_stream.py\nimport asyncio\nimport json\nimport os\nimport time\n\nimport httpx\n\nfrom app.ai_client import API_KEY, BASE_URL, MODEL, NotConfigured\n\nFALLBACK_MODEL = os.getenv("AI_FALLBACK_MODEL", "").strip()\nFIRST_MS = int(os.getenv("AI_FIRST_TIMEOUT_MS", "15000") or 15000)\nIDLE_MS = int(os.getenv("AI_IDLE_TIMEOUT_MS", "20000") or 20000)\nTOTAL_MS = int(os.getenv("AI_TIMEOUT_MS", "60000") or 60000)\n\n\nclass ThinkSplitter:\n    def __init__(self, on_think, on_answer):\n        self.mode = "init"\n        self.buf = ""\n        self.on_think = on_think\n        self.on_answer = on_answer\n\n    def feed_chunk(self, chunk):\n        # TODO 1：实现 init / think / answer 三态拆分；think 态用 self.buf.rfind("<") 保留可能是 </think> 前缀的尾巴\n        ...\n\n    def flush(self):\n        if not self.buf:\n            return\n        if self.mode == "think":\n            self.on_think(self.buf)\n        else:\n            self.on_answer(self.buf)\n        self.buf = ""\n\n\nasync def stream_attempt(model, messages, on_think, on_delta):\n    # TODO 2：用 httpx.AsyncClient() 的 client.stream("POST", ... stream=True) 读取 SSE；\n    #         用 asyncio.wait_for(lines.__anext__(), timeout=...) 控制首字超时、空闲看门狗与总时长截止；\n    #         把 delta.reasoning_content 和 delta.content 交给 on_think 与 ThinkSplitter\n    return False\n\n\nasync def stream_with_fallback(messages, on_model, on_think, on_delta, on_reset):\n    """依次尝试主模型与备用模型；已输出过半截内容时先回调 on_reset 再切换"""\n    if not API_KEY:\n        raise NotConfigured("AI 评分还没有配置")\n    # TODO 3：构造候选列表 [MODEL, FALLBACK_MODEL]，循环调用 stream_attempt，\n    #         失败且 wrote 为 True 时先 await on_reset() 再试备用模型\n    raise RuntimeError("未实现")',explain:[{at:'# app/ai_stream.py',to:'TOTAL_MS = int(os.getenv("AI_TIMEOUT_MS", "60000") or 60000)',text:'复用 ai_client 的地址、密钥、主模型，再读出备用模型与三段超时时间。'},{at:'class ThinkSplitter:',to:'self.on_answer = on_answer',text:'拆分器初始化为 init 状态并保存两个回调。'},{at:'def feed_chunk(self, chunk):',to:'...',text:'分片解析方法，要你补全。'},{at:'def flush(self):',to:'self.buf = ""',text:'流结束吐净残余字符。'},{at:'async def stream_attempt(model, messages, on_think, on_delta):',to:'return False',text:'异步单次流式请求与三段超时控制，要你补全。'},{at:'async def stream_with_fallback(',to:'raise RuntimeError("未实现")',text:'主备降级循环，要你补全。'}],solution:{code:'# app/ai_stream.py\nimport asyncio\nimport json\nimport os\nimport time\n\nimport httpx\n\nfrom app.ai_client import API_KEY, BASE_URL, MODEL, NotConfigured\n\nFALLBACK_MODEL = os.getenv("AI_FALLBACK_MODEL", "").strip()\nFIRST_MS = int(os.getenv("AI_FIRST_TIMEOUT_MS", "15000") or 15000)\nIDLE_MS = int(os.getenv("AI_IDLE_TIMEOUT_MS", "20000") or 20000)\nTOTAL_MS = int(os.getenv("AI_TIMEOUT_MS", "60000") or 60000)\n\n\nclass ThinkSplitter:\n    def __init__(self, on_think, on_answer):\n        self.mode = "init"\n        self.buf = ""\n        self.on_think = on_think\n        self.on_answer = on_answer\n\n    def feed_chunk(self, chunk):\n        if not chunk:\n            return\n        if self.mode == "answer":\n            self.on_answer(chunk)\n            return\n        self.buf += chunk\n        if self.mode == "init":\n            trimmed = self.buf.lstrip()\n            if not trimmed:\n                return\n            if trimmed.startswith("<think>"):\n                self.buf = trimmed[len("<think>"):]\n                self.mode = "think"\n            elif "<think>".startswith(trimmed):\n                return\n            else:\n                self.mode = "answer"\n                self.on_answer(self.buf)\n                self.buf = ""\n                return\n        while self.mode == "think":\n            close_idx = self.buf.find("</think>")\n            if close_idx >= 0:\n                if close_idx > 0:\n                    self.on_think(self.buf[:close_idx])\n                rest = self.buf[close_idx + len("</think>"):]\n                self.buf = ""\n                self.mode = "answer"\n                if rest:\n                    self.on_answer(rest)\n                return\n            last_lt = self.buf.rfind("<")\n            if last_lt >= 0 and "</think>".startswith(self.buf[last_lt:]):\n                if last_lt > 0:\n                    self.on_think(self.buf[:last_lt])\n                self.buf = self.buf[last_lt:]\n                return\n            if self.buf:\n                self.on_think(self.buf)\n                self.buf = ""\n            return\n\n    def flush(self):\n        if not self.buf:\n            return\n        if self.mode == "think":\n            self.on_think(self.buf)\n        else:\n            self.on_answer(self.buf)\n        self.buf = ""\n\n\nasync def stream_attempt(model, messages, on_think, on_delta):\n    deadline = time.monotonic() + TOTAL_MS / 1000\n    alive = False\n    wrote = False\n    splitter = ThinkSplitter(\n        lambda t: on_think(t),\n        lambda t: on_delta(t),\n    )\n\n    def emit_think(text):\n        nonlocal wrote\n        wrote = True\n        on_think(text)\n\n    def emit_answer(text):\n        nonlocal wrote\n        wrote = True\n        on_delta(text)\n\n    splitter.on_think = emit_think\n    splitter.on_answer = emit_answer\n    try:\n        async with httpx.AsyncClient(timeout=httpx.Timeout(None, connect=10.0)) as client:\n            async with client.stream(\n                "POST",\n                f"{BASE_URL}/chat/completions",\n                headers={"Authorization": f"Bearer {API_KEY}"},\n                json={"model": model, "temperature": 0.5, "messages": messages, "stream": True},\n            ) as resp:\n                resp.raise_for_status()\n                lines = resp.aiter_lines()\n                while True:\n                    wait = min((IDLE_MS if alive else FIRST_MS) / 1000, deadline - time.monotonic())\n                    if wait <= 0:\n                        raise TimeoutError("流式超时")\n                    try:\n                        raw = await asyncio.wait_for(lines.__anext__(), timeout=wait)\n                    except StopAsyncIteration:\n                        splitter.flush()\n                        return wrote\n                    line = raw.strip()\n                    if not line.startswith("data:"):\n                        continue\n                    payload = line[5:].strip()\n                    if payload == "[DONE]":\n                        splitter.flush()\n                        return wrote\n                    try:\n                        delta = json.loads(payload)["choices"][0]["delta"]\n                    except (ValueError, KeyError, IndexError):\n                        continue\n                    alive = True\n                    if delta.get("reasoning_content"):\n                        emit_think(delta["reasoning_content"])\n                    if delta.get("content"):\n                        splitter.feed_chunk(delta["content"])\n    except Exception as err:\n        err.wrote = wrote\n        raise\n\n\nasync def stream_with_fallback(messages, on_model, on_think, on_delta, on_reset):\n    """依次尝试主模型与备用模型；已输出过半截内容时先回调 on_reset 再切换"""\n    if not API_KEY:\n        raise NotConfigured("AI 评分还没有配置")\n    candidates = [MODEL, FALLBACK_MODEL] if FALLBACK_MODEL and FALLBACK_MODEL != MODEL else [MODEL]\n    last_err = None\n    for idx, model in enumerate(candidates):\n        await on_model(model, idx > 0)\n        try:\n            await stream_attempt(model, messages, on_think, on_delta)\n            return model\n        except asyncio.CancelledError:\n            raise\n        except Exception as err:\n            last_err = err\n            if getattr(err, "wrote", False) and idx + 1 < len(candidates):\n                await on_reset()\n    raise last_err',explain:[{at:'# app/ai_stream.py',to:'TOTAL_MS = int(os.getenv("AI_TIMEOUT_MS", "60000") or 60000)',text:'复用 ai_client 配置并读取备用模型及三段毫秒超时。'},{at:'class ThinkSplitter:',to:'self.on_answer = on_answer',text:'拆分器初始化为 init 状态并保存两个回调。'},{at:'def feed_chunk(self, chunk):',to:'    def flush(self):',text:'三态拆分器：在 init 阶段识别开头的 <think>，在 think 阶段只保留可能是 </think> 前缀的小段尾巴，answer 阶段直接透传。'},{at:'def flush(self):',to:'        self.buf = ""',text:'流结束时按当前状态吐出残余缓冲并清空。'},{at:'async def stream_attempt(',to:'splitter.on_answer = emit_answer',text:'记录 deadline 和是否已经产出内容 wrote，确保异常时知道要不要通知前端 reset。'},{at:'try:',to:'resp.raise_for_status()',text:'把 httpx 自带读写超时交给下面的 asyncio.wait_for 精细控制，只保留 10 秒连接超时。'},{at:'lines = resp.aiter_lines()',to:'return wrote',text:'每行等待时间取“首字或空闲超时”与“总剩余时间”的较小值；超时抛出 TimeoutError，流结束时 flush。'},{at:'line = raw.strip()',to:'splitter.feed_chunk(delta["content"])',text:'解析 SSE data: 行，收到合法 delta 后把 alive 改为 True（进入空闲看门狗阶段），分别输出思考与正文。'},{at:'except Exception as err:',to:'raise',text:'把 wrote 标记带出异常，方便上层判断是否重置。'},{at:'async def stream_with_fallback(',to:'raise last_err',text:'依次尝试主备模型；注意必须原样向上抛出 asyncio.CancelledError（前端断开连接时立即停止，不要误当失败去降级）。'}]}}}},
  {title:'任务二：SSE / NDJSON 流式接口与超时控制',body:'把任务一的流式客户端接到第 15 关的对话服务和接口上：先做参数、权限和次数校验，然后发 NDJSON 响应头、定期发 ping 心跳、感知客户端断开取消上游，全部成功后再把干净的正文存库并返回 done。',variants:{go:{practice:{steps:['新建 internal/handler/chat_stream.go（用到了第 15 关 internal/service/chat.go 里的校验与存储逻辑），补完 TODO 1 到 3。','在 internal/handler/handler.go 的 Routes 里注册 mux.HandleFunc("POST /api/chats/stream", h.streamChat)，并确保 ChatService 暴露 PrepareStream / SaveStreamTurn 方法。','go build ./... 确认没有报错。'],expect:'go build ./... 没有输出'},code:'// internal/service/chat.go（在 ChatService 上新增两个辅助方法供流式接口调用）\nfunc (s *ChatService) PrepareStream(userID, chatID int, questionID *int, message string) (text string, qid *int, msgs []ai.Message, used int, err error) {\n    text = strings.TrimSpace(message)\n    if text == "" || utf8.RuneCountInString(text) > 1000 {\n        return "", nil, nil, 0, ErrBadMessage\n    }\n    var history []store.ChatMessage\n    if chatID != 0 {\n        chat, err := s.chats.Get(userID, chatID)\n        if errors.Is(err, store.ErrNotFound) {\n            return "", nil, nil, 0, ErrChatNotFound\n        }\n        if err != nil {\n            return "", nil, nil, 0, err\n        }\n        questionID = chat.QuestionID\n        if history, err = s.chats.Messages(chatID); err != nil {\n            return "", nil, nil, 0, err\n        }\n        if len(history) > chatHistory {\n            history = history[len(history)-chatHistory:]\n        }\n    } else if questionID != nil {\n        if _, err := s.questions.Get(*questionID); err != nil {\n            return "", nil, nil, 0, err\n        }\n    }\n    used, ok, err := s.chats.TakeQuota(userID, s.limit)\n    if err != nil {\n        return "", nil, nil, 0, err\n    }\n    if !ok {\n        return "", nil, nil, 0, ErrQuotaExceeded\n    }\n    msgs = []ai.Message{{Role: "system", Content: s.systemPrompt(questionID)}}\n    for _, m := range history {\n        msgs = append(msgs, ai.Message{Role: m.Role, Content: m.Content})\n    }\n    msgs = append(msgs, ai.Message{Role: "user", Content: text})\n    return text, questionID, msgs, used, nil\n}\n\nfunc (s *ChatService) FinishStream(userID, chatID int, questionID *int, text, reply string, used int) (ChatReply, error) {\n    reply = strings.TrimSpace(reply)\n    title := []rune(text)\n    if len(title) > 20 {\n        title = title[:20]\n    }\n    id, err := s.chats.SaveTurn(userID, chatID, questionID, string(title), text, reply)\n    if err != nil {\n        return ChatReply{}, err\n    }\n    return ChatReply{ChatID: id, Reply: reply, Remaining: s.limit - used}, nil\n}\n\nfunc (s *ChatService) RefundStreamQuota(userID int) {\n    _ = s.chats.RefundQuota(userID)\n}\n\n// internal/handler/chat_stream.go\npackage handler\n\nimport (\n    "encoding/json"\n    "errors"\n    "net/http"\n    "strings"\n    "sync"\n    "time"\n\n    "zixishi/internal/ai"\n    "zixishi/internal/service"\n)\n\nfunc (h *Handler) streamChat(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireUser(w, r)\n    if !ok {\n        return\n    }\n    var body struct {\n        ChatID     int    `json:"chatId"`\n        QuestionID *int   `json:"questionId"`\n        Message    string `json:"message"`\n    }\n    json.NewDecoder(r.Body).Decode(&body)\n    text, qid, msgs, used, err := h.chats.PrepareStream(u.ID, body.ChatID, body.QuestionID, body.Message)\n    if err != nil {\n        h.chatError(w, err)\n        return\n    }\n    // TODO 1：设置流式响应头 Content-Type: application/x-ndjson; charset=utf-8、Cache-Control: no-store, no-transform、\n    //         X-Accel-Buffering: no，用 http.NewResponseController(w) 和 sync.Mutex 写出并发安全的 emit 函数（每次 Flush）\n    // TODO 2：写出 {"t":"start"}，启动 10 秒心跳 goroutine 定期发 {"t":"ping"}（结束时停止）\n    // TODO 3：调用 ai.Client.StreamWithFallback（ctx 传 r.Context()，自动响应前端断连）：\n    //         累加干净的正文（reset 时清空），失败且未写出或全部模型出错时退回次数并写 {"t":"error"}，\n    //         成功时调用 h.chats.FinishStream 落库并发送 {"t":"done","chatId":…,"model":…,"remaining":…}\n    _, _, _, _ = text, qid, msgs, used\n}',explain:[{at:'// internal/service/chat.go',to:'return text, questionID, msgs, used, nil',text:'把第 15 关的校验、取最近 10 条历史和占用次数拆成 PrepareStream，开流前调用；参数或额度有问题直接返回标准错误码。'},{at:'func (s *ChatService) FinishStream(',to:'_ = s.chats.RefundQuota(userID)',text:'FinishStream 只把干净的正文写进数据库；RefundStreamQuota 在全部模型出错或前端未收到内容就中断时退回次数。'},{at:'// internal/handler/chat_stream.go',to:'"zixishi/internal/service"',text:'流式接口放在新文件里，需要 sync.Mutex 保护流写入与心跳协程不打架。'},{at:'func (h *Handler) streamChat(',to:'// TODO 1',text:'先认人、解析请求体并执行开流前校验；若出错直接走 chatError 返回 JSON 状态码。'},{at:'// TODO 1',to:'_, _, _, _ = text, qid, msgs, used',text:'写出流式响应头、并发安全的 emit、心跳协程和流式调用兜底逻辑，要你补全。'}],solution:{code:'// internal/service/chat.go（在 ChatService 上新增三个辅助方法供流式接口调用，以及 AIService / Handler 共享 aiClient）\nfunc (s *ChatService) AI() *ai.Client { return s.ai }\n\nfunc (s *ChatService) PrepareStream(userID, chatID int, questionID *int, message string) (text string, qid *int, msgs []ai.Message, used int, err error) {\n    text = strings.TrimSpace(message)\n    if text == "" || utf8.RuneCountInString(text) > 1000 {\n        return "", nil, nil, 0, ErrBadMessage\n    }\n    var history []store.ChatMessage\n    if chatID != 0 {\n        chat, err := s.chats.Get(userID, chatID)\n        if errors.Is(err, store.ErrNotFound) {\n            return "", nil, nil, 0, ErrChatNotFound\n        }\n        if err != nil {\n            return "", nil, nil, 0, err\n        }\n        questionID = chat.QuestionID\n        if history, err = s.chats.Messages(chatID); err != nil {\n            return "", nil, nil, 0, err\n        }\n        if len(history) > chatHistory {\n            history = history[len(history)-chatHistory:]\n        }\n    } else if questionID != nil {\n        if _, err := s.questions.Get(*questionID); err != nil {\n            return "", nil, nil, 0, err\n        }\n    }\n    used, ok, err := s.chats.TakeQuota(userID, s.limit)\n    if err != nil {\n        return "", nil, nil, 0, err\n    }\n    if !ok {\n        return "", nil, nil, 0, ErrQuotaExceeded\n    }\n    msgs = []ai.Message{{Role: "system", Content: s.systemPrompt(questionID)}}\n    for _, m := range history {\n        msgs = append(msgs, ai.Message{Role: m.Role, Content: m.Content})\n    }\n    msgs = append(msgs, ai.Message{Role: "user", Content: text})\n    return text, questionID, msgs, used, nil\n}\n\nfunc (s *ChatService) FinishStream(userID, chatID int, questionID *int, text, reply string, used int) (ChatReply, error) {\n    reply = strings.TrimSpace(reply)\n    title := []rune(text)\n    if len(title) > 20 {\n        title = title[:20]\n    }\n    id, err := s.chats.SaveTurn(userID, chatID, questionID, string(title), text, reply)\n    if err != nil {\n        return ChatReply{}, err\n    }\n    return ChatReply{ChatID: id, Reply: reply, Remaining: s.limit - used}, nil\n}\n\nfunc (s *ChatService) RefundStreamQuota(userID int) {\n    _ = s.chats.RefundQuota(userID)\n}\n\n// internal/handler/chat_stream.go\npackage handler\n\nimport (\n    "encoding/json"\n    "errors"\n    "net/http"\n    "strings"\n    "sync"\n    "time"\n\n    "zixishi/internal/ai"\n    "zixishi/internal/service"\n)\n\nfunc (h *Handler) streamChat(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireUser(w, r)\n    if !ok {\n        return\n    }\n    var body struct {\n        ChatID     int    `json:"chatId"`\n        QuestionID *int   `json:"questionId"`\n        Message    string `json:"message"`\n    }\n    json.NewDecoder(r.Body).Decode(&body)\n    text, qid, msgs, used, err := h.chats.PrepareStream(u.ID, body.ChatID, body.QuestionID, body.Message)\n    if err != nil {\n        h.chatError(w, err)\n        return\n    }\n    w.Header().Set("Content-Type", "application/x-ndjson; charset=utf-8")\n    w.Header().Set("Cache-Control", "no-store, no-transform")\n    w.Header().Set("X-Accel-Buffering", "no")\n    rc := http.NewResponseController(w)\n    var mu sync.Mutex\n    emit := func(ev map[string]any) {\n        mu.Lock()\n        defer mu.Unlock()\n        _ = json.NewEncoder(w).Encode(ev)\n        _ = rc.Flush()\n    }\n    emit(map[string]any{"t": "start"})\n    stopHB := make(chan struct{})\n    go func() {\n        ticker := time.NewTicker(10 * time.Second)\n        defer ticker.Stop()\n        for {\n            select {\n            case <-stopHB:\n                return\n            case <-r.Context().Done():\n                return\n            case <-ticker.C:\n                emit(map[string]any{"t": "ping"})\n            }\n        }\n    }()\n    defer close(stopHB)\n\n    var answer strings.Builder\n    wrote := false\n    modelUsed, err := h.chats.AI().StreamWithFallback(r.Context(), msgs, 0.5, ai.StreamCallbacks{\n        OnModel: func(m string, fb bool) {\n            emit(map[string]any{"t": "model", "model": m, "fallback": fb})\n        },\n        OnThink: func(t string) {\n            wrote = true\n            emit(map[string]any{"t": "think", "text": t})\n        },\n        OnDelta: func(t string) {\n            wrote = true\n            answer.WriteString(t)\n            emit(map[string]any{"t": "delta", "text": t})\n        },\n        OnReset: func() {\n            answer.Reset()\n            emit(map[string]any{"t": "reset"})\n        },\n    })\n    if err != nil {\n        if r.Context().Err() != nil {\n            if !wrote {\n                h.chats.RefundStreamQuota(u.ID)\n            }\n            return\n        }\n        h.chats.RefundStreamQuota(u.ID)\n        if errors.Is(err, ai.ErrNotConfigured) {\n            emit(map[string]any{"t": "error", "message": err.Error()})\n            return\n        }\n        emit(map[string]any{"t": "error", "message": service.ErrAIFailed.Error()})\n        return\n    }\n    saved, err := h.chats.FinishStream(u.ID, body.ChatID, qid, text, answer.String(), used)\n    if err != nil {\n        h.chats.RefundStreamQuota(u.ID)\n        emit(map[string]any{"t": "error", "message": "保存对话失败"})\n        return\n    }\n    emit(map[string]any{"t": "done", "chatId": saved.ChatID, "model": modelUsed, "remaining": saved.Remaining})\n}',explain:[{at:'// internal/service/chat.go',to:'return text, questionID, msgs, used, nil',text:'校验、取历史、占额度都在流开始前做完。'},{at:'func (s *ChatService) FinishStream(',to:'_ = s.chats.RefundQuota(userID)',text:'生成完成后只保存干净的正文；失败或提前中断时退回次数。'},{at:'// internal/handler/chat_stream.go',to:'w.Header().Set("Content-Type",',text:'先认人并做开流前校验，不合格时正常返回 400 / 401 / 404 / 429 JSON。'},{at:'w.Header().Set("Content-Type",',to:'_ = rc.Flush()',text:'设置 NDJSON 响应头与防缓冲头，并用互斥锁保护每次写完一行立刻 Flush 出去。'},{at:'emit(map[string]any{"t": "start"})',to:'defer close(stopHB)',text:'先推 start，再开协程每 10 秒推一次 ping 心跳，函数退出时自动关掉定时器。'},{at:'var answer strings.Builder',to:'emit(map[string]any{"t": "reset"})',text:'把 r.Context() 传给流式客户端：只要前端点停止或关页面，上游请求立即中止。主模型降级触发 OnReset 时清空 answer 缓冲并通知前端。'},{at:'if err != nil {',to:'saved, err := h.chats.FinishStream(',text:'若是前端主动断连且还没输出任何内容，退回次数后静默结束；若上游全部模型都失败，退回次数并发送 error 事件。'},{at:'saved, err := h.chats.FinishStream(',to:'emit(map[string]any{"t": "done",',text:'全部成功后只把正文存进数据库，再推送 done 事件给前端。'}]}},java:{practice:{steps:['在 application.properties 里加上 spring.mvc.async.request-timeout=120000，确保长流不会被 MVC 默认 30 秒异步超时掐断。','新建 controller/ChatStreamController.java，补完 TODO 1 到 3。','启动服务，用 mvn spring-boot:run 验证接口可编译运行。'],expect:'服务启动无报错，POST /api/chats/stream 可流式响应'},code:'// controller/ChatStreamController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.ai.*;\nimport com.example.zixishi.model.Question;\nimport com.example.zixishi.repository.ChatRepository;\nimport com.example.zixishi.repository.QuestionRepository;\nimport com.example.zixishi.service.AuthService;\nimport com.example.zixishi.service.StudyService;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport java.io.*;\nimport java.nio.charset.StandardCharsets;\nimport java.util.*;\nimport java.util.concurrent.*;\nimport java.util.concurrent.atomic.*;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.http.*;\nimport org.springframework.web.bind.annotation.*;\nimport org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;\n\n@RestController\npublic class ChatStreamController {\n\n    public record StreamBody(Integer chatId, Integer questionId, String message) {}\n\n    private static final int HISTORY = 10;\n    private static final String TUTOR_PROMPT = "你是面试自习室的 AI 老师，学生是初学者。用简短、通俗的中文回答，必要时举一个小例子。";\n\n    private final AuthService auth;\n    private final AiStreamClient aiStream;\n    private final ChatRepository chats;\n    private final QuestionRepository questions;\n    private final ObjectMapper mapper;\n    private final int dailyLimit;\n    private final ScheduledExecutorService heartbeats = Executors.newScheduledThreadPool(2, r -> {\n        Thread t = new Thread(r, "chat-heartbeat");\n        t.setDaemon(true);\n        return t;\n    });\n\n    public ChatStreamController(AuthService auth, AiStreamClient aiStream, ChatRepository chats,\n                                QuestionRepository questions, ObjectMapper mapper,\n                                @Value("${chat.daily-limit:20}") int dailyLimit) {\n        this.auth = auth;\n        this.aiStream = aiStream;\n        this.chats = chats;\n        this.questions = questions;\n        this.mapper = mapper;\n        this.dailyLimit = Math.max(dailyLimit, 1);\n    }\n\n    @PostMapping("/api/chats/stream")\n    public ResponseEntity<StreamingResponseBody> stream(@CookieValue(name = "session", required = false) String token,\n                                                        @RequestBody StreamBody body) {\n        int userId = auth.currentUser(token).id();\n        String text = body.message() == null ? "" : body.message().strip();\n        if (text.isEmpty() || text.codePointCount(0, text.length()) > 1000) {\n            throw new StudyService.StudyException(400, "消息不能为空，最多 1000 个字");\n        }\n        // TODO 1：复用第 15 关逻辑检查 chatId / questionId 是否存在、取最近 HISTORY 条历史，并调用 chats.takeQuota 占额度\n        // TODO 2：返回 ResponseEntity<StreamingResponseBody>，设置 Content-Type: application/x-ndjson; charset=utf-8、\n        //         Cache-Control: no-store, no-transform 和 X-Accel-Buffering: no\n        // TODO 3：在 StreamingResponseBody 里加锁写 NDJSON 事件（write + flush，IOException 时置 aborted=true 并关闭 activeBody）；\n        //         启动 10 秒心跳，调用 aiStream.streamWithFallback，成功调用 chats.saveTurn 并发 done，失败退额度并发 error\n        return ResponseEntity.ok().build();\n    }\n}\n\n# application.properties（调大异步流式接口超时，避免被 Spring 默认 30 秒打断）\nspring.mvc.async.request-timeout=120000',explain:[{at:'// controller/ChatStreamController.java',to:'public class ChatStreamController {',text:'流式控制器：返回 StreamingResponseBody，把每一行 NDJSON 实时刷到客户端。'},{at:'public record StreamBody(',to:'});',text:'定义请求体、历史条数限制和守护线程心跳池。'},{at:'public ChatStreamController(',to:'this.dailyLimit = Math.max(dailyLimit, 1);',text:'注入认证、流式客户端、对话与题目仓库。'},{at:'@PostMapping("/api/chats/stream")',to:'throw new StudyService.StudyException(400, "消息不能为空，最多 1000 个字");',text:'先认人并做文本校验，不合规在进入流式前直接抛异常返回 401 / 400。'},{at:'// TODO 1',to:'return ResponseEntity.ok().build();',text:'开流前完成权限/额度校验，设置防缓冲响应头，并在流体里做心跳、断连感知、落库与退回次数，要你补全。'},{at:'# application.properties',to:'spring.mvc.async.request-timeout=120000',text:'Spring Boot 默认给异步流设了 30 秒上限，调大到 120 秒由我们的三段看门狗接管。'}],solution:{code:'// controller/ChatStreamController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.ai.*;\nimport com.example.zixishi.model.Question;\nimport com.example.zixishi.repository.ChatRepository;\nimport com.example.zixishi.repository.QuestionRepository;\nimport com.example.zixishi.service.AuthService;\nimport com.example.zixishi.service.StudyService;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport java.io.*;\nimport java.nio.charset.StandardCharsets;\nimport java.util.*;\nimport java.util.concurrent.*;\nimport java.util.concurrent.atomic.*;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.http.*;\nimport org.springframework.web.bind.annotation.*;\nimport org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;\n\n@RestController\npublic class ChatStreamController {\n\n    public record StreamBody(Integer chatId, Integer questionId, String message) {}\n\n    private static final int HISTORY = 10;\n    private static final String TUTOR_PROMPT = "你是面试自习室的 AI 老师，学生是初学者。用简短、通俗的中文回答，必要时举一个小例子。";\n\n    private final AuthService auth;\n    private final AiStreamClient aiStream;\n    private final ChatRepository chats;\n    private final QuestionRepository questions;\n    private final ObjectMapper mapper;\n    private final int dailyLimit;\n    private final ScheduledExecutorService heartbeats = Executors.newScheduledThreadPool(2, r -> {\n        Thread t = new Thread(r, "chat-heartbeat");\n        t.setDaemon(true);\n        return t;\n    });\n\n    public ChatStreamController(AuthService auth, AiStreamClient aiStream, ChatRepository chats,\n                                QuestionRepository questions, ObjectMapper mapper,\n                                @Value("${chat.daily-limit:20}") int dailyLimit) {\n        this.auth = auth;\n        this.aiStream = aiStream;\n        this.chats = chats;\n        this.questions = questions;\n        this.mapper = mapper;\n        this.dailyLimit = Math.max(dailyLimit, 1);\n    }\n\n    private String systemPrompt(Integer qid) {\n        Question q = qid == null ? null : questions.findById(qid).orElse(null);\n        return q == null ? TUTOR_PROMPT : TUTOR_PROMPT + "\\n学生正在看这道题：" + q.title() + "\\n参考答案：" + q.answer();\n    }\n\n    @PostMapping("/api/chats/stream")\n    public ResponseEntity<StreamingResponseBody> stream(@CookieValue(name = "session", required = false) String token,\n                                                        @RequestBody StreamBody body) {\n        int userId = auth.currentUser(token).id();\n        String text = body.message() == null ? "" : body.message().strip();\n        if (text.isEmpty() || text.codePointCount(0, text.length()) > 1000) {\n            throw new StudyService.StudyException(400, "消息不能为空，最多 1000 个字");\n        }\n        Integer chatId = body.chatId();\n        Integer questionId = body.questionId();\n        List<ChatRepository.ChatMessage> history = List.of();\n        if (chatId != null) {\n            ChatRepository.Chat c = chats.find(userId, chatId).orElseThrow(() -> new StudyService.StudyException(404, "对话不存在"));\n            questionId = c.questionId();\n            List<ChatRepository.ChatMessage> all = chats.messages(chatId);\n            history = all.subList(Math.max(all.size() - HISTORY, 0), all.size());\n        } else if (questionId != null && questions.findById(questionId).isEmpty()) {\n            throw new StudyService.StudyException(404, "题目不存在");\n        }\n        int used = chats.takeQuota(userId, dailyLimit).orElseThrow(() -> new StudyService.StudyException(429, "今天的提问次数用完了，明天再来"));\n        List<AiClient.Message> messages = new ArrayList<>();\n        messages.add(new AiClient.Message("system", systemPrompt(questionId)));\n        for (var m : history) messages.add(new AiClient.Message(m.role(), m.content()));\n        messages.add(new AiClient.Message("user", text));\n        final Integer finalQid = questionId;\n\n        StreamingResponseBody bodyStream = out -> {\n            Object writeLock = new Object();\n            AtomicBoolean aborted = new AtomicBoolean(false);\n            AtomicBoolean wrote = new AtomicBoolean(false);\n            AtomicReference<InputStream> activeBody = new AtomicReference<>();\n            Runnable abortUpstream = () -> {\n                aborted.set(true);\n                InputStream in = activeBody.get();\n                if (in != null) try { in.close(); } catch (IOException ignored) {}\n            };\n            java.util.function.Consumer<Map<String, Object>> send = ev -> {\n                if (aborted.get()) return;\n                synchronized (writeLock) {\n                    try {\n                        out.write((mapper.writeValueAsString(ev) + "\\n").getBytes(StandardCharsets.UTF_8));\n                        out.flush();\n                    } catch (IOException e) {\n                        abortUpstream.run();\n                    }\n                }\n            };\n            send.accept(Map.of("t", "start"));\n            ScheduledFuture<?> hb = heartbeats.scheduleAtFixedRate(() -> send.accept(Map.of("t", "ping")), 10, 10, TimeUnit.SECONDS);\n            StringBuilder answer = new StringBuilder();\n            try {\n                String usedModel = aiStream.streamWithFallback(messages, aborted, activeBody, new AiStreamClient.Callbacks() {\n                    public void onModel(String m, boolean fb) { send.accept(Map.of("t", "model", "model", m, "fallback", fb)); }\n                    public void onThink(String t) { wrote.set(true); send.accept(Map.of("t", "think", "text", t)); }\n                    public void onDelta(String t) { wrote.set(true); answer.append(t); send.accept(Map.of("t", "delta", "text", t)); }\n                    public void onReset() { answer.setLength(0); send.accept(Map.of("t", "reset")); }\n                });\n                String title = text.substring(0, text.offsetByCodePoints(0, Math.min(20, text.codePointCount(0, text.length()))));\n                int savedId = chats.saveTurn(userId, chatId, finalQid, title, text, answer.toString().strip());\n                send.accept(Map.of("t", "done", "chatId", savedId, "model", usedModel, "remaining", dailyLimit - used));\n            } catch (AiClient.NotConfiguredException e) {\n                chats.refundQuota(userId);\n                send.accept(Map.of("t", "error", "message", e.getMessage()));\n            } catch (Exception e) {\n                if (aborted.get()) { if (!wrote.get()) chats.refundQuota(userId); }\n                else { chats.refundQuota(userId); send.accept(Map.of("t", "error", "message", "AI 服务暂时不可用，请稍后再试")); }\n            } finally {\n                hb.cancel(false);\n            }\n        };\n        return ResponseEntity.ok()\n            .contentType(MediaType.parseMediaType("application/x-ndjson; charset=utf-8"))\n            .header("Cache-Control", "no-store, no-transform").header("X-Accel-Buffering", "no").body(bodyStream);\n    }\n}\n\n# application.properties（调大异步流式接口超时，避免被 Spring 默认 30 秒打断）\nspring.mvc.async.request-timeout=120000',explain:[{at:'// controller/ChatStreamController.java',to:'this.dailyLimit = Math.max(dailyLimit, 1);',text:'流式控制器初始化并准备后台心跳定时器。'},{at:'private String systemPrompt(',to:'return q == null ?',text:'把关联题目和参考答案放进系统提示词。'},{at:'@PostMapping("/api/chats/stream")',to:'final Integer finalQid = questionId;',text:'在开始流式之前完成登录检查、参数校验、对话归属校验、取历史以及占额度，保证不合规时照常返回 400 / 401 / 404 / 429。'},{at:'StreamingResponseBody bodyStream = out -> {',to:'if (in != null) try { in.close(); } catch (IOException ignored) {}',text:'准备写锁和客户端断开中止回调：只要往 out 写数据抛 IOException，说明客户端已断开，立刻关闭上游输入流止损。'},{at:'java.util.function.Consumer<Map<String, Object>> send = ev -> {',to:'send.accept(Map.of("t", "start"));',text:'加锁保证心跳和增量不会把两行 JSON 写交叉，每次写完立刻 flush 推出去。'},{at:'ScheduledFuture<?> hb =',to:'StringBuilder answer = new StringBuilder();',text:'每 10 秒推一行 ping 保活。'},{at:'try {',to:'send.accept(Map.of("t", "done",',text:'执行主备降级流式，主模型失败切换时先清零 answer，全部成功后再把干净正文落库并发出 done。'},{at:'} catch (AiClient.NotConfiguredException e) {',to:'hb.cancel(false);',text:'未配置或全部模型失败时退回次数并发出 error 事件；客户端主动中断且还未输出时也退回次数。'},{at:'return ResponseEntity.ok()',to:'.header("Cache-Control", "no-store, no-transform").header("X-Accel-Buffering", "no").body(bodyStream);',text:'加上流式类型和防缓冲响应头并返回。'},{at:'# application.properties',to:'spring.mvc.async.request-timeout=120000',text:'调大 Spring MVC 异步请求默认 30 秒限制，把超时控制权交给看门狗。'}]}},node:{practice:{steps:['新建 src/routes/chat_stream.js，补完 TODO 1 到 3。','在 app.js 的 chat 路由前挂载：app.use("/api", require("./src/routes/chat_stream"));。','node -e "require(\'./src/routes/chat_stream\')" 确认可加载。'],expect:'命令正常退出，无报错'},code:'// src/routes/chat_stream.js\nconst express = require("express");\nconst { requireUser } = require("../middleware");\nconst { getQuestion } = require("../db/questions");\nconst store = require("../db/chat");\nconst { NotConfiguredError } = require("../ai/client");\nconst { streamWithFallback } = require("../ai/stream");\n\nconst router = express.Router();\nconst DAILY_LIMIT = Math.max(Number(process.env.CHAT_DAILY_LIMIT) || 20, 1);\nconst HISTORY = 10;\nconst TUTOR_PROMPT = "你是面试自习室的 AI 老师，学生是初学者。用简短、通俗的中文回答，必要时举一个小例子。";\n\nfunction systemPrompt(questionId) {\n  const q = questionId ? getQuestion(questionId) : null;\n  return q ? `${TUTOR_PROMPT}\\n学生正在看这道题：${q.title}\\n参考答案：${q.answer}` : TUTOR_PROMPT;\n}\n\nrouter.post("/chats/stream", requireUser, async (req, res) => {\n  const text = typeof req.body?.message === "string" ? req.body.message.trim() : "";\n  if (!text || [...text].length > 1000) return res.status(400).json({ error: "消息不能为空，最多 1000 个字" });\n  if (!process.env.AI_API_KEY) return res.status(503).json({ error: "AI 评分还没有配置" });\n  // TODO 1：校验 chatId（存在且是自己的，否则 404）或 questionId（存在，否则 404），取最近 HISTORY 条消息并 takeQuota（用完返回 429）\n  // TODO 2：设置 Content-Type: application/x-ndjson; charset=utf-8、Cache-Control: no-store, no-transform、X-Accel-Buffering: no，\n  //         并调用 res.flushHeaders()；用 res.on("close", () => { if (!res.writableEnded) ctl.abort(); }) 监听中断\n  // TODO 3：启动 10 秒 ping 定时器，调用 streamWithFallback：reset 时清空 answer，\n  //         完成时 store.saveTurn 存干净正文并发 done；失败退回次数并视情况发 error\n});\n\nmodule.exports = router;',explain:[{at:'// src/routes/chat_stream.js',to:'const TUTOR_PROMPT =',text:'流式路由复用第 15 关的题目/对话存储与中间件，加上任务一写的 streamWithFallback。'},{at:'function systemPrompt(questionId) {',to:'}',text:'如果对话关联了题目，把题干和参考答案放进系统提示词。'},{at:'router.post("/chats/stream", requireUser,',to:'if (!process.env.AI_API_KEY)',text:'先认人、校验输入长度和密钥是否配置，在进入流式前直接返回 400 / 401 / 503。'},{at:'// TODO 1',to:'module.exports = router;',text:'完成权限额度校验、流式响应头、res.on("close") 监听中断、心跳和落库退次，要你补全。'}],solution:{code:'// src/routes/chat_stream.js\nconst express = require("express");\nconst { requireUser } = require("../middleware");\nconst { getQuestion } = require("../db/questions");\nconst store = require("../db/chat");\nconst { NotConfiguredError } = require("../ai/client");\nconst { streamWithFallback } = require("../ai/stream");\n\nconst router = express.Router();\nconst DAILY_LIMIT = Math.max(Number(process.env.CHAT_DAILY_LIMIT) || 20, 1);\nconst HISTORY = 10;\nconst TUTOR_PROMPT = "你是面试自习室的 AI 老师，学生是初学者。用简短、通俗的中文回答，必要时举一个小例子。";\n\nfunction systemPrompt(questionId) {\n  const q = questionId ? getQuestion(questionId) : null;\n  return q ? `${TUTOR_PROMPT}\\n学生正在看这道题：${q.title}\\n参考答案：${q.answer}` : TUTOR_PROMPT;\n}\n\nrouter.post("/chats/stream", requireUser, async (req, res) => {\n  const text = typeof req.body?.message === "string" ? req.body.message.trim() : "";\n  if (!text || [...text].length > 1000) return res.status(400).json({ error: "消息不能为空，最多 1000 个字" });\n  if (!process.env.AI_API_KEY) return res.status(503).json({ error: "AI 评分还没有配置" });\n  let chatId = req.body?.chatId != null ? Number(req.body.chatId) : null;\n  let questionId = req.body?.questionId != null ? Number(req.body.questionId) : null;\n  let history = [];\n  if (chatId !== null) {\n    const chat = store.getChat(req.user.id, chatId);\n    if (!chat) return res.status(404).json({ error: "对话不存在" });\n    questionId = chat.questionId;\n    history = store.listMessages(chatId).slice(-HISTORY);\n  } else if (questionId !== null && !getQuestion(questionId)) {\n    return res.status(404).json({ error: "题目不存在" });\n  }\n  const used = store.takeQuota(req.user.id, DAILY_LIMIT);\n  if (used === null) return res.status(429).json({ error: "今天的提问次数用完了，明天再来" });\n\n  const messages = [\n    { role: "system", content: systemPrompt(questionId) },\n    ...history.map((m) => ({ role: m.role, content: m.content })),\n    { role: "user", content: text },\n  ];\n  res.setHeader("Content-Type", "application/x-ndjson; charset=utf-8");\n  res.setHeader("Cache-Control", "no-store, no-transform");\n  res.setHeader("X-Accel-Buffering", "no");\n  res.flushHeaders();\n\n  const ctl = new AbortController();\n  res.on("close", () => { if (!res.writableEnded) ctl.abort(); });\n  const send = (ev) => { if (!res.writableEnded) res.write(JSON.stringify(ev) + "\\n"); };\n  send({ t: "start" });\n  const hb = setInterval(() => send({ t: "ping" }), 10000);\n  let answer = "", wrote = false;\n  try {\n    const modelUsed = await streamWithFallback(messages, ctl.signal, {\n      onModel: (model, fallback) => send({ t: "model", model, fallback }),\n      onThink: (t) => { wrote = true; send({ t: "think", text: t }); },\n      onDelta: (t) => { wrote = true; answer += t; send({ t: "delta", text: t }); },\n      onReset: () => { answer = ""; send({ t: "reset" }); },\n    });\n    const id = store.saveTurn(req.user.id, chatId, questionId, [...text].slice(0, 20).join(""), text, answer.trim());\n    send({ t: "done", chatId: id, model: modelUsed, remaining: DAILY_LIMIT - used });\n  } catch (err) {\n    if (ctl.signal.aborted) {\n      if (!wrote) store.refundQuota(req.user.id);\n    } else {\n      store.refundQuota(req.user.id);\n      const msg = err instanceof NotConfiguredError ? err.message : "AI 服务暂时不可用，请稍后再试";\n      send({ t: "error", message: msg });\n    }\n  } finally {\n    clearInterval(hb);\n    res.end();\n  }\n});\n\nmodule.exports = router;',explain:[{at:'// src/routes/chat_stream.js',to:': TUTOR_PROMPT;',text:'复用第 15 关的题目、对话与用户中间件，引入任务一的 streamWithFallback，并将题干与参考答案拼入系统提示词。'},{at:'router.post("/chats/stream",',to:'return res.status(429).json({ error: "今天的提问次数用完了，明天再来" });',text:'开流之前做好长度、密钥、对话/题目归属以及占额度校验，出错直接返回对应的 JSON 状态码。'},{at:'const messages = [',to:'res.flushHeaders();',text:'拼好带最近 10 条历史的消息列表，设置防缓冲响应头并立刻刷出响应头。'},{at:'const ctl = new AbortController();',to:'let answer = "", wrote = false;',text:'关键细节：必须监听 res.on("close") 且确认 !res.writableEnded 才中止（不能用 req.on("close")，因为 POST 请求体读完 req 就会触发 close）；随后发 start 并开 10 秒心跳。'},{at:'try {',to:'send({ t: "done",',text:'主备降级流式输出，发生 reset 时清零 answer，全部成功后再把干净正文存数据库并推 done。'},{at:'} catch (err) {',to:'res.end();',text:'若是前端主动断连且没吐过内容，静默退额度；若是所有模型都失败，退额度并推 error；finally 里清掉定时器并结束响应。'},{at:'module.exports = router;',text:'导出流式路由。'}]}},python:{practice:{steps:['新建 app/routers/chat_stream.py，补完 TODO 1 到 3。','在 main.py 的 chat 路由前导入并挂载：app.include_router(chat_stream.router)。','python -c "import app.routers.chat_stream" 确认导入正常。'],expect:'命令正常退出，无报错'},code:'# app/routers/chat_stream.py\nimport asyncio\nimport json\n\nfrom fastapi import APIRouter, Depends\nfrom fastapi.responses import StreamingResponse\nfrom pydantic import BaseModel\n\nfrom app import ai_client, ai_stream\nfrom app import chat as store\nfrom app.db import get_question\nfrom app.routers.study import require_user\nfrom app.services.chat import DAILY_LIMIT, HISTORY, ChatError, system_prompt\n\nrouter = APIRouter(prefix="/api")\n\n\nclass StreamBody(BaseModel):\n    chatId: int | None = None\n    questionId: int | None = None\n    message: str = ""\n\n\n@router.post("/chats/stream")\nasync def chat_stream(body: StreamBody, user=Depends(require_user)):\n    text = body.message.strip() if isinstance(body.message, str) else ""\n    if not text or len(text) > 1000:\n        raise ChatError(400, "消息不能为空，最多 1000 个字")\n    if not ai_client.API_KEY:\n        raise ChatError(503, "AI 评分还没有配置")\n    # TODO 1：复用第 15 关逻辑校验 chatId / questionId（不存在抛 ChatError(404)），取最近 HISTORY 条历史，调用 store.take_quota（空则 429）\n    # TODO 2：用 asyncio.Queue() 把 ai_stream.stream_with_fallback 的回调事件与队列消费解耦；\n    #         用 asyncio.wait_for(queue.get(), timeout=10) 在等待超过 10 秒时自动产出 {"t": "ping"} 心跳\n    # TODO 3：在 async def generate() 的 try...finally 里感知 asyncio.CancelledError（前端断连时取消后台流任务、\n    #         未写出内容则退额度）；全部成功时调用 store.save_turn 存干净正文并产出 done，失败则退额度并产出 error\n    return StreamingResponse(iter([]), media_type="application/x-ndjson")',explain:[{at:'# app/routers/chat_stream.py',to:'router = APIRouter(prefix="/api")',text:'导入第 15 关的对话存储、ChatError 与任务一的 ai_stream。'},{at:'class StreamBody(BaseModel):',to:'message: str = ""',text:'流式请求体：chatId 可空，为空时新建对话。'},{at:'@router.post("/chats/stream")',to:'raise ChatError(503, "AI 评分还没有配置")',text:'先认人、校验消息长度并确认已配置密钥，否则提前抛 ChatError 返回 400 / 401 / 503。'},{at:'# TODO 1',to:'return StreamingResponse(iter([]), media_type="application/x-ndjson")',text:'用 # 注释标出三处核心步骤：开流前校验占额度、队列加超时心跳、取消感知与落库退额度，要你补全。'}],solution:{code:'# app/routers/chat_stream.py\nimport asyncio\nimport json\n\nfrom fastapi import APIRouter, Depends\nfrom fastapi.responses import StreamingResponse\nfrom pydantic import BaseModel\n\nfrom app import ai_client, ai_stream\nfrom app import chat as store\nfrom app.db import get_question\nfrom app.routers.study import require_user\nfrom app.services.chat import DAILY_LIMIT, HISTORY, ChatError, system_prompt\n\nrouter = APIRouter(prefix="/api")\n\n\nclass StreamBody(BaseModel):\n    chatId: int | None = None\n    questionId: int | None = None\n    message: str = ""\n\n\n@router.post("/chats/stream")\nasync def chat_stream(body: StreamBody, user=Depends(require_user)):\n    text = body.message.strip() if isinstance(body.message, str) else ""\n    if not text or len(text) > 1000:\n        raise ChatError(400, "消息不能为空，最多 1000 个字")\n    if not ai_client.API_KEY:\n        raise ChatError(503, "AI 评分还没有配置")\n    chat_id, question_id, history = body.chatId, body.questionId, []\n    if chat_id is not None:\n        chat = store.get_chat(user["id"], chat_id)\n        if chat is None:\n            raise ChatError(404, "对话不存在")\n        question_id = chat["questionId"]\n        history = store.list_messages(chat_id)[-HISTORY:]\n    elif question_id is not None and get_question(question_id) is None:\n        raise ChatError(404, "题目不存在")\n    used = store.take_quota(user["id"], DAILY_LIMIT)\n    if used is None:\n        raise ChatError(429, "今天的提问次数用完了，明天再来")\n    messages = [{"role": "system", "content": system_prompt(question_id)}]\n    messages += [{"role": m["role"], "content": m["content"]} for m in history]\n    messages.append({"role": "user", "content": text})\n\n    async def generate():\n        queue = asyncio.Queue()\n        answer_parts, wrote = [], False\n        yield json.dumps({"t": "start"}, ensure_ascii=False) + "\\n"\n\n        async def on_model(m, fb):\n            await queue.put({"t": "model", "model": m, "fallback": fb})\n\n        def on_think(t):\n            nonlocal wrote\n            wrote = True\n            queue.put_nowait({"t": "think", "text": t})\n\n        def on_delta(t):\n            nonlocal wrote\n            wrote = True\n            answer_parts.append(t)\n            queue.put_nowait({"t": "delta", "text": t})\n\n        async def on_reset():\n            answer_parts.clear()\n            await queue.put({"t": "reset"})\n\n        async def produce():\n            try:\n                model_used = await ai_stream.stream_with_fallback(messages, on_model, on_think, on_delta, on_reset)\n                clean_reply = "".join(answer_parts).strip()\n                saved_id = store.save_turn(user["id"], chat_id, question_id, text[:20], text, clean_reply)\n                await queue.put({"t": "done", "chatId": saved_id, "model": model_used, "remaining": DAILY_LIMIT - used})\n            except ai_client.NotConfigured as e:\n                store.refund_quota(user["id"])\n                await queue.put({"t": "error", "message": str(e)})\n            except asyncio.CancelledError:\n                raise\n            except Exception:\n                store.refund_quota(user["id"])\n                await queue.put({"t": "error", "message": "AI 服务暂时不可用，请稍后再试"})\n            finally:\n                await queue.put(None)\n\n        task = asyncio.create_task(produce())\n        try:\n            while True:\n                try:\n                    ev = await asyncio.wait_for(queue.get(), timeout=10.0)\n                except asyncio.TimeoutError:\n                    yield json.dumps({"t": "ping"}, ensure_ascii=False) + "\\n"\n                    continue\n                if ev is None:\n                    break\n                yield json.dumps(ev, ensure_ascii=False) + "\\n"\n        except asyncio.CancelledError:\n            if not wrote:\n                store.refund_quota(user["id"])\n            raise\n        finally:\n            task.cancel()\n\n    headers = {"Cache-Control": "no-store, no-transform", "X-Accel-Buffering": "no"}\n    return StreamingResponse(generate(), media_type="application/x-ndjson; charset=utf-8", headers=headers)',explain:[{at:'# app/routers/chat_stream.py',to:'router = APIRouter(prefix="/api")',text:'导入第 15 关的对话存储、ChatError 与任务一的 ai_stream。'},{at:'class StreamBody(BaseModel):',to:'messages.append({"role": "user", "content": text})',text:'在进入流式响应前校验对话/题目归属、加载最近 10 条历史并扣减一次额度。'},{at:'async def generate():',to:'yield json.dumps({"t": "start"}, ensure_ascii=False) + "\\n"',text:'生成器一开始先推 start 事件，建立队列和答案拼接列表。'},{at:'async def on_model(',to:'await queue.put({"t": "reset"})',text:'四个回调分别往队列推送模型切换、思考增量、正文增量和重置清空。'},{at:'async def produce():',to:'await queue.put(None)',text:'后台协程执行主备降级流，成功时把干净正文存数据库并发 done；全部失败则退额度并发 error；最后放 None 哨兵结束循环。'},{at:'task = asyncio.create_task(produce())',to:'yield json.dumps(ev, ensure_ascii=False) + "\\n"',text:'利用 asyncio.wait_for(..., timeout=10.0) 一举两得：超过 10 秒没新事件就自动产出一行 ping 心跳。'},{at:'except asyncio.CancelledError:',to:'task.cancel()',text:'客户端一断开，FastAPI 会取消生成器任务；若还没吐出过内容则退回次数，并在 finally 里取消后台 task，立即关闭上游 HTTP 连接。'},{at:'headers =',to:'return StreamingResponse(generate(),',text:'带上 NDJSON 内容类型和防缓冲头返回流式响应。'}]}}}},
  {title:'任务三：前端流式阅读、思考折叠与“停止生成”按钮',body:'前端用 fetch 加 ReadableStream 按行解析 NDJSON：收到 think 时展开思考折叠面板并实时更新；正文 delta 一到就收起思考面板并计算“已思考 N 秒”，主模型触发 reset 时清空当前残缺内容；点击“停止生成”调用 AbortController 立即中止。如果用的是后端模板渲染，也可以直接在题目对话页里嵌入同样的一小段原生 JS 脚本实现流式增强。',variants:{html:{body:'在原生 HTML + JS 的题目详情页里把“发送”升级成流式阅读：用 <details> 放思考过程，边读边打字，点“停止生成”立刻中断。',practice:{steps:['在 question.html 的“问 AI 老师”区域加上流式面板和“停止生成”按钮。','在 question.js 里补完 TODO 1 到 3，接上 /api/chats/stream。','登录后提问，观察思考先展开、正文到达时自动折叠，中途点“停止生成”立即停止。'],expect:'思考面板实时显示“思考中…”，正文输出后变为“已思考 N 秒”并自动折叠；点“停止生成”后不再追加文字'},code:'<!-- question.html：替换第 15 关的“问 AI 老师”区块 -->\n<section>\n  <h2>问 AI 老师</h2>\n  <div id="chatLog"></div>\n  <details id="thinkBox" hidden>\n    <summary id="thinkLabel">思考过程</summary>\n    <pre id="thinkBody"></pre>\n  </details>\n  <p id="liveAnswer"></p>\n  <textarea id="chatInput" rows="3" cols="60" maxlength="1000" placeholder="输入追问"></textarea>\n  <p>\n    <button id="chatSend">发送</button>\n    <button id="chatStop" type="button" disabled>停止生成</button>\n    <span id="chatHint"></span>\n  </p>\n</section>\n\n// question.js：流式发送与中断逻辑（保留之前的 loadChat 和 addMessage）\nlet abortCtl = null;\n\ndocument.getElementById("chatStop").addEventListener("click", () => {\n  abortCtl?.abort();\n});\n\ndocument.getElementById("chatSend").addEventListener("click", async () => {\n  const input = document.getElementById("chatInput");\n  const hint = document.getElementById("chatHint");\n  const thinkBox = document.getElementById("thinkBox");\n  const thinkLabel = document.getElementById("thinkLabel");\n  const thinkBody = document.getElementById("thinkBody");\n  const live = document.getElementById("liveAnswer");\n  const sendBtn = document.getElementById("chatSend");\n  const stopBtn = document.getElementById("chatStop");\n  const message = input.value.trim();\n  if (!message || abortCtl) return;\n\n  abortCtl = new AbortController();\n  sendBtn.disabled = true;\n  stopBtn.disabled = false;\n  thinkBox.hidden = true; thinkBox.open = false;\n  thinkBody.textContent = ""; live.textContent = ""; hint.textContent = "";\n  let thinkText = "", answerText = "", thinkStart = 0, thinkDone = false;\n\n  // TODO 1：封装 handleEvent(ev)：think 追加到 thinkBody 并展开 thinkBox；\n  //         delta 到达时若刚结束思考就计算秒数、更新 thinkLabel 并折叠 thinkBox，然后追加 live.textContent；\n  //         reset 清空 thinkText/answerText 和界面；done 记下 chatId 并写入 chatLog；error 显示错误信息\n  try {\n    // TODO 2：fetch("/api/chats/stream", { method: "POST", signal: abortCtl.signal, ... })；\n    //         若 !res.ok 读取 JSON 错误并提示；否则用 res.body.getReader() + TextDecoder({ stream: true }) 按换行解析 NDJSON\n  } catch (err) {\n    // TODO 3：err.name === "AbortError" 时提示“已停止生成”，否则显示 err.message\n  } finally {\n    abortCtl = null;\n    sendBtn.disabled = false;\n    stopBtn.disabled = true;\n  }\n});',explain:[{at:'<!-- question.html',to:'</section>',text:'用原生 <details> 元素承载可折叠的思考面板，平时隐藏，收到思考事件再打开；下方 liveAnswer 实时展示正在吐出的正文，旁边放上“停止生成”按钮。'},{at:'// question.js',to:'abortCtl?.abort();',text:'保存当前请求的 AbortController，点“停止生成”时直接调用 abort() 掐断连接和读取。'},{at:'document.getElementById("chatSend").addEventListener("click", async () => {',to:'if (!message || abortCtl) return;',text:'取出输入框和界面节点，防止上一段还在生成时重复点击。'},{at:'abortCtl = new AbortController();',to:'let thinkText = "",',text:'初始化本轮请求状态与清空上一轮临时思考/正文展示。'},{at:'// TODO 1',to:'stopBtn.disabled = true;',text:'在 TODO 1 到 3 里补全逐行解析 NDJSON、事件分发、中断提示和 finally 复位。'}],solution:{code:'<!-- question.html：替换第 15 关的“问 AI 老师”区块 -->\n<section>\n  <h2>问 AI 老师</h2>\n  <div id="chatLog"></div>\n  <details id="thinkBox" hidden>\n    <summary id="thinkLabel">思考过程</summary>\n    <pre id="thinkBody"></pre>\n  </details>\n  <p id="liveAnswer"></p>\n  <textarea id="chatInput" rows="3" cols="60" maxlength="1000" placeholder="输入追问"></textarea>\n  <p>\n    <button id="chatSend">发送</button>\n    <button id="chatStop" type="button" disabled>停止生成</button>\n    <span id="chatHint"></span>\n  </p>\n</section>\n\n// question.js：流式发送与中断逻辑（保留之前的 loadChat 和 addMessage）\nlet abortCtl = null;\n\ndocument.getElementById("chatStop").addEventListener("click", () => {\n  abortCtl?.abort();\n});\n\ndocument.getElementById("chatSend").addEventListener("click", async () => {\n  const input = document.getElementById("chatInput");\n  const hint = document.getElementById("chatHint");\n  const thinkBox = document.getElementById("thinkBox");\n  const thinkLabel = document.getElementById("thinkLabel");\n  const thinkBody = document.getElementById("thinkBody");\n  const live = document.getElementById("liveAnswer");\n  const sendBtn = document.getElementById("chatSend");\n  const stopBtn = document.getElementById("chatStop");\n  const message = input.value.trim();\n  if (!message || abortCtl) return;\n\n  abortCtl = new AbortController();\n  sendBtn.disabled = true;\n  stopBtn.disabled = false;\n  thinkBox.hidden = true; thinkBox.open = false;\n  thinkBody.textContent = ""; live.textContent = ""; hint.textContent = "";\n  let thinkText = "", answerText = "", thinkStart = 0, thinkDone = false;\n\n  function handleEvent(ev) {\n    if (ev.t === "think") {\n      if (!thinkStart) thinkStart = Date.now();\n      thinkText += ev.text;\n      thinkBox.hidden = false; thinkBox.open = true;\n      thinkLabel.textContent = "思考中…";\n      thinkBody.textContent = thinkText;\n    } else if (ev.t === "delta") {\n      if (thinkStart && !thinkDone) {\n        thinkDone = true;\n        const secs = Math.max(1, Math.round((Date.now() - thinkStart) / 1000));\n        thinkLabel.textContent = `已思考 ${secs} 秒`;\n        thinkBox.open = false;\n      }\n      answerText += ev.text;\n      live.textContent = answerText;\n    } else if (ev.t === "reset") {\n      thinkText = ""; answerText = ""; thinkStart = 0; thinkDone = false;\n      thinkBox.hidden = true; thinkBody.textContent = ""; live.textContent = "";\n    } else if (ev.t === "done") {\n      chatId = ev.chatId;\n      addMessage("user", message);\n      addMessage("assistant", answerText);\n      live.textContent = "";\n      input.value = "";\n      hint.textContent = `今天还可以问 ${ev.remaining} 次`;\n    } else if (ev.t === "error") {\n      hint.textContent = ev.message;\n    }\n  }\n\n  try {\n    const res = await fetch("/api/chats/stream", {\n      method: "POST",\n      headers: { "Content-Type": "application/json" },\n      body: JSON.stringify({ chatId, questionId: Number(id), message }),\n      signal: abortCtl.signal,\n    });\n    if (!res.ok) {\n      const errData = await res.json().catch(() => ({}));\n      throw new Error(res.status === 401 ? "请先登录" : (errData.error || "请求失败"));\n    }\n    const reader = res.body.getReader(), dec = new TextDecoder();\n    let buf = "";\n    while (true) {\n      const { done, value } = await reader.read();\n      if (done) break;\n      buf += dec.decode(value, { stream: true });\n      let i;\n      while ((i = buf.indexOf("\\n")) >= 0) {\n        const line = buf.slice(0, i).trim();\n        buf = buf.slice(i + 1);\n        if (line) handleEvent(JSON.parse(line));\n      }\n    }\n    if (buf.trim()) handleEvent(JSON.parse(buf.trim()));\n  } catch (err) {\n    hint.textContent = err.name === "AbortError" ? "已停止生成" : err.message;\n  } finally {\n    abortCtl = null;\n    sendBtn.disabled = false;\n    stopBtn.disabled = true;\n  }\n});',explain:[{at:'<!-- question.html',to:'</section>',text:'原生 <details> 实现思考过程折叠面板，和旁边的“停止生成”按钮。'},{at:'// question.js',to:'let thinkText = "",',text:'点击发送后准备 AbortController 并复位界面；点击停止时调用 abort()。'},{at:'function handleEvent(ev) {',to:'thinkBody.textContent = thinkText;',text:'收到 think 事件时记录开始时间、展开思考面板并实时显示思考过程。'},{at:'} else if (ev.t === "delta") {',to:'live.textContent = answerText;',text:'收到第一段正文 delta 时结算思考秒数并自动折叠思考面板，同时把正文打在页面上。'},{at:'} else if (ev.t === "reset") {',to:'hint.textContent = ev.message;',text:'reset 清空残缺状态准备重来；done 落位为正式聊天记录并清空输入；error 展示失败说明；ping 不命中任何分支自动忽略。'},{at:'try {',to:'if (buf.trim()) handleEvent(JSON.parse(buf.trim()));',text:'带上 signal 发 POST 请求，用 ReadableStream 逐行切分 NDJSON（别忘了最后流结束时处理可能没带换行的末尾 buf）。'},{at:'} catch (err) {',to:'stopBtn.disabled = true;',text:'如果是用户点击停止引发的 AbortError 提示“已停止生成”，最后恢复按钮状态。'}]}},react:{body:'在 React 版 ChatPanel 组件里接入 /api/chats/stream，用状态管理思考面板折叠、流式正文、reset 清空和 AbortController 中断。',practice:{steps:['更新 src/ChatPanel.jsx，补完 TODO 1 到 3。','运行 npm run build（或启动开发服务器）打开一道题测试发送与停止生成。'],expect:'思考面板实时显示“思考中…”，正文到达后自动折叠为“已思考 N 秒”；点“停止生成”立即停流'},code:'// src/ChatPanel.jsx\nimport { useEffect, useRef, useState } from "react";\n\nexport default function ChatPanel({ questionId }) {\n  const [chatId, setChatId] = useState(null);\n  const [messages, setMessages] = useState([]);\n  const [input, setInput] = useState("");\n  const [busy, setBusy] = useState(false);\n  const [hint, setHint] = useState("");\n  const [think, setThink] = useState(null);\n  const [liveAnswer, setLiveAnswer] = useState("");\n  const abortRef = useRef(null);\n\n  useEffect(() => {\n    let ignore = false;\n    async function load() {\n      const res = await fetch("/api/chats");\n      if (!res.ok) return;\n      const mine = (await res.json()).find((c) => c.questionId === questionId);\n      if (!mine) return;\n      const detail = await (await fetch(`/api/chats/${mine.id}`)).json();\n      if (ignore) return;\n      setChatId(mine.id); setMessages(detail.messages);\n    }\n    load().catch(() => {});\n    return () => { ignore = true; abortRef.current?.abort(); };\n  }, [questionId]);\n\n  async function send() {\n    const message = input.trim();\n    if (!message || busy) return;\n    const ctl = new AbortController();\n    abortRef.current = ctl;\n    setBusy(true); setHint(""); setThink(null); setLiveAnswer("");\n    // TODO 1：定义局部变量 thinkText、answerText、thinkStart、thinkDone 及事件处理函数 handleEvent(ev)\n    // TODO 2：fetch("/api/chats/stream", { method: "POST", signal: ctl.signal, ... })，\n    //         按换行解析 res.body 流并调用 handleEvent(ev)\n    // TODO 3：catch 里区分 AbortError（提示“已停止生成”）和其他错误；finally 复位 abortRef 与 busy\n  }\n\n  return (\n    <section>\n      <h2>问 AI 老师</h2>\n      {messages.map((m, i) => <p key={i}>{m.role === "user" ? "我：" : "AI 老师："}{m.content}</p>)}\n      {think && (\n        <details open={think.live}>\n          <summary>{think.live ? "思考中…" : `已思考 ${think.secs} 秒`}</summary>\n          <pre>{think.text}</pre>\n        </details>\n      )}\n      {liveAnswer && <p>{liveAnswer}</p>}\n      <textarea rows={3} cols={60} maxLength={1000} placeholder="输入追问"\n        value={input} onChange={(e) => setInput(e.target.value)} />\n      <p>\n        <button onClick={send} disabled={busy}>发送</button>\n        <button type="button" onClick={() => abortRef.current?.abort()} disabled={!busy}>停止生成</button>\n        <span>{hint}</span>\n      </p>\n    </section>\n  );\n}',explain:[{at:'// src/ChatPanel.jsx',to:'const abortRef = useRef(null);',text:'新增 think（含 text/secs/live）、liveAnswer 状态和存 AbortController 的 ref。'},{at:'useEffect(() => {',to:'}, [questionId]);',text:'加载历史记录；切换题目或卸载组件时顺便中止还没跑完的流请求。'},{at:'async function send() {',to:'setBusy(true); setHint(""); setThink(null); setLiveAnswer("");',text:'创建 AbortController 并清零上一轮的流式状态。'},{at:'// TODO 1',to:'// TODO 3',text:'补完事件分发、ReadableStream 按行读流和异常处理，要你补全。'},{at:'return (',to:'</details>',text:'渲染历史记录，以及由 think.live 控制展开/自动收起的思考面板。'},{at:'{liveAnswer && <p>{liveAnswer}</p>}',to:'</section>',text:'流式输出中的正文与发送/停止按钮。'}],solution:{code:'// src/ChatPanel.jsx\nimport { useEffect, useRef, useState } from "react";\n\nexport default function ChatPanel({ questionId }) {\n  const [chatId, setChatId] = useState(null);\n  const [messages, setMessages] = useState([]);\n  const [input, setInput] = useState("");\n  const [busy, setBusy] = useState(false);\n  const [hint, setHint] = useState("");\n  const [think, setThink] = useState(null);\n  const [liveAnswer, setLiveAnswer] = useState("");\n  const abortRef = useRef(null);\n\n  useEffect(() => {\n    let ignore = false;\n    async function load() {\n      const res = await fetch("/api/chats");\n      if (!res.ok) return;\n      const mine = (await res.json()).find((c) => c.questionId === questionId);\n      if (!mine) return;\n      const detail = await (await fetch(`/api/chats/${mine.id}`)).json();\n      if (ignore) return;\n      setChatId(mine.id); setMessages(detail.messages);\n    }\n    load().catch(() => {});\n    return () => { ignore = true; abortRef.current?.abort(); };\n  }, [questionId]);\n\n  async function send() {\n    const message = input.trim();\n    if (!message || busy) return;\n    const ctl = new AbortController();\n    abortRef.current = ctl;\n    setBusy(true); setHint(""); setThink(null); setLiveAnswer("");\n    let thinkText = "", answerText = "", thinkStart = 0, thinkDone = false;\n\n    function handleEvent(ev) {\n      if (ev.t === "think") {\n        if (!thinkStart) thinkStart = Date.now();\n        thinkText += ev.text;\n        setThink({ text: thinkText, live: true });\n      } else if (ev.t === "delta") {\n        if (thinkStart && !thinkDone) {\n          thinkDone = true;\n          const secs = Math.max(1, Math.round((Date.now() - thinkStart) / 1000));\n          setThink({ text: thinkText, secs, live: false });\n        }\n        answerText += ev.text;\n        setLiveAnswer(answerText);\n      } else if (ev.t === "reset") {\n        thinkText = ""; answerText = ""; thinkStart = 0; thinkDone = false;\n        setThink(null); setLiveAnswer("");\n      } else if (ev.t === "done") {\n        setChatId(ev.chatId);\n        setMessages((list) => [...list, { role: "user", content: message }, { role: "assistant", content: answerText }]);\n        setLiveAnswer(""); setInput("");\n        setHint(`今天还可以问 ${ev.remaining} 次`);\n      } else if (ev.t === "error") {\n        setHint(ev.message);\n      }\n    }\n\n    try {\n      const res = await fetch("/api/chats/stream", {\n        method: "POST",\n        headers: { "Content-Type": "application/json" },\n        body: JSON.stringify({ chatId, questionId, message }),\n        signal: ctl.signal,\n      });\n      if (!res.ok) {\n        const errData = await res.json().catch(() => ({}));\n        throw new Error(res.status === 401 ? "请先登录" : (errData.error || "请求失败"));\n      }\n      const reader = res.body.getReader(), dec = new TextDecoder();\n      let buf = "";\n      while (true) {\n        const { done, value } = await reader.read();\n        if (done) break;\n        buf += dec.decode(value, { stream: true });\n        let i;\n        while ((i = buf.indexOf("\\n")) >= 0) {\n          const line = buf.slice(0, i).trim();\n          buf = buf.slice(i + 1);\n          if (line) handleEvent(JSON.parse(line));\n        }\n      }\n      if (buf.trim()) handleEvent(JSON.parse(buf.trim()));\n    } catch (err) {\n      setHint(err.name === "AbortError" ? "已停止生成" : err.message);\n    } finally {\n      abortRef.current = null;\n      setBusy(false);\n    }\n  }\n\n  return (\n    <section>\n      <h2>问 AI 老师</h2>\n      {messages.map((m, i) => <p key={i}>{m.role === "user" ? "我：" : "AI 老师："}{m.content}</p>)}\n      {think && (\n        <details open={think.live}>\n          <summary>{think.live ? "思考中…" : `已思考 ${think.secs} 秒`}</summary>\n          <pre>{think.text}</pre>\n        </details>\n      )}\n      {liveAnswer && <p>{liveAnswer}</p>}\n      <textarea rows={3} cols={60} maxLength={1000} placeholder="输入追问"\n        value={input} onChange={(e) => setInput(e.target.value)} />\n      <p>\n        <button onClick={send} disabled={busy}>发送</button>\n        <button type="button" onClick={() => abortRef.current?.abort()} disabled={!busy}>停止生成</button>\n        <span>{hint}</span>\n      </p>\n    </section>\n  );\n}',explain:[{at:'// src/ChatPanel.jsx',to:'}, [questionId]);',text:'组件卸载或题目变化时自动清理并中止未完成的流请求。'},{at:'async function send() {',to:'let thinkText = "",',text:'初始化本轮控制句柄与临时累积变量。'},{at:'function handleEvent(ev) {',to:'setThink({ text: thinkText, live: true });',text:'思考中保持 live 为 true，让 <details> 处于展开态。'},{at:'} else if (ev.t === "delta") {',to:'setLiveAnswer(answerText);',text:'正文一来立刻算秒数把 live 置 false 自动收起思考，并实时刷新 liveAnswer。'},{at:'} else if (ev.t === "reset") {',to:'setHint(ev.message);',text:'reset 清空状态重来；done 把整段回答追加进消息历史并提示剩余次数。'},{at:'try {',to:'if (buf.trim()) handleEvent(JSON.parse(buf.trim()));',text:'读取流并按换行符拆解 NDJSON 事件。'},{at:'} catch (err) {',to:'setBusy(false);',text:'捕获 AbortError 显示停止提示，并在 finally 恢复状态。'},{at:'return (',to:'</section>',text:'把思考面板、实时回答以及发送/停止按钮组合起来。'}]}}}}
  ,{title:'验收：检查流式分段、思考分离、中断和降级',body:'验收脚本会在本机 8090 端口启动一个支持 SSE 分块发送的“假大模型服务”。为了在几秒内快速验完超时和降级逻辑，启动后端前需要额外设置较短的超时和备用模型：\nAI_BASE_URL=http://127.0.0.1:8090\nAI_API_KEY=test-key\nAI_MODEL=primary-model\nAI_FALLBACK_MODEL=backup-model\nAI_FIRST_TIMEOUT_MS=800\nAI_IDLE_TIMEOUT_MS=800\nAI_TIMEOUT_MS=5000\nCHAT_DAILY_LIMIT=10\n脚本会逐项验证：未登录拦截、流式分块增量到达、跨分片的 <think>…</think> 拆分与干净入库、reasoning_content 归类、前端断开连接后及时止损、主模型半路卡死触发 reset 并降级，以及全模型失败退回次数。',practice:{steps:['停掉后端，按上面设置好环境变量再启动。','把下面代码保存为 checks/check_l16.py，运行 python checks/check_l16.py，直到通过 7 / 7。','打开网页端题目页，实际体验流式打字、思考折叠和点击“停止生成”。'],expect:'✓ 未登录调用流式接口返回 401\n✓ 流式增量分块到达（首段早于结束）\n✓ 跨分片的 <think>...</think> 正确拆分为 think 与 delta\n✓ reasoning_content 字段也能归类为 think 事件\n✓ 前端断开连接后后端及时中止上游\n✓ 主模型半路卡死时触发 reset 并降级到备用模型\n✓ 全部模型失败时返回 error 事件并退回次数\n\n通过 7 / 7'},code:`import http.cookiejar
import json
import random
import sys
import threading
import time
import urllib.error
import urllib.request
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

BASE = sys.argv[1] if len(sys.argv) > 1 else "http://localhost:8080"
state = {"slow_chunks": 0, "slow_aborted": False}
passed = 0


class FakeStreamLLM(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def read_body(self):
        if self.headers.get("Content-Length"):
            return self.rfile.read(int(self.headers["Content-Length"]))
        data = b""
        while True:
            size = int(self.rfile.readline().strip(), 16)
            if size == 0:
                self.rfile.readline()
                return data
            data += self.rfile.read(size)
            self.rfile.readline()

    def write_sse(self, obj):
        line = "data: " + (obj if isinstance(obj, str) else json.dumps(obj, ensure_ascii=False)) + "\\n\\n"
        raw = line.encode("utf-8")
        self.wfile.write(f"{len(raw):x}\\r\\n".encode("ascii") + raw + b"\\r\\n")
        self.wfile.flush()

    def start_sse(self):
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream; charset=utf-8")
        self.send_header("Transfer-Encoding", "chunked")
        self.send_header("Connection", "close")
        self.end_headers()

    def reply_json(self, status, data):
        raw = json.dumps(data, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(raw)))
        self.send_header("Connection", "close")
        self.end_headers()
        self.wfile.write(raw)

    def do_POST(self):
        body = json.loads(self.read_body())
        model = body.get("model", "")
        last = (body.get("messages") or [{}])[-1].get("content", "")
        if "全部失败" in last:
            return self.reply_json(500, {"error": {"message": "all down"}})
        self.start_sse()
        try:
            if "主模型卡死" in last:
                if model == "primary-model":
                    self.write_sse({"choices": [{"delta": {"content": "半截内容"}}]})
                    time.sleep(2.0)
                    return
                self.write_sse({"choices": [{"delta": {"content": "已由备用模型回答"}}]})
            elif "慢速流" in last:
                for i in range(20):
                    self.write_sse({"choices": [{"delta": {"content": f"第{i}段 "}}]})
                    state["slow_chunks"] += 1
                    time.sleep(0.15)
            elif "带思考标签" in last:
                for part in ("<thi", "nk>先理清", "作用域</th", "ink>defer 在函数返回前执行。"):
                    self.write_sse({"choices": [{"delta": {"content": part}}]})
                    time.sleep(0.05)
            elif "字段推理" in last:
                self.write_sse({"choices": [{"delta": {"reasoning_content": "逐层排查"}}]})
                time.sleep(0.05)
                self.write_sse({"choices": [{"delta": {"content": "检查响应头即可。"}}]})
            else:
                for part in ("第一段 ", "第二段 ", "第三段"):
                    self.write_sse({"choices": [{"delta": {"content": part}}]})
                    time.sleep(0.25)
            self.write_sse("[DONE]")
            self.wfile.write(b"0\\r\\n\\r\\n")
            self.wfile.flush()
        except OSError:
            if "慢速流" in last:
                state["slow_aborted"] = True

    def log_message(self, *args):
        pass


threading.Thread(target=ThreadingHTTPServer(("127.0.0.1", 8090), FakeStreamLLM).serve_forever, daemon=True).start()


def check(name, ok):
    global passed
    print(("✓ " if ok else "✗ ") + name)
    passed += bool(ok)


opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()))


def call_json(method, path, body=None):
    data = json.dumps(body).encode("utf-8") if body is not None else None
    req = urllib.request.Request(BASE + path, data=data, method=method, headers={"Content-Type": "application/json"})
    try:
        with opener.open(req, timeout=15) as r:
            return r.status, json.loads(r.read().decode("utf-8") or "null")
    except urllib.error.HTTPError as e:
        return e.code, json.loads(e.read().decode("utf-8") or "null")


def open_stream(body):
    req = urllib.request.Request(
        BASE + "/api/chats/stream",
        data=json.dumps(body).encode("utf-8"),
        method="POST",
        headers={"Content-Type": "application/json"},
    )
    return opener.open(req, timeout=15)


def collect_stream(body):
    t0 = time.monotonic()
    first_dt, events = None, []
    with open_stream(body) as resp:
        for raw in resp:
            line = raw.decode("utf-8").strip()
            if not line:
                continue
            ev = json.loads(line)
            if ev.get("t") == "delta" and first_dt is None:
                first_dt = time.monotonic() - t0
            events.append(ev)
    return events, first_dt, time.monotonic() - t0


try:
    status_401, _ = call_json("POST", "/api/chats/stream", {"message": "你好"})
except OSError as e:
    sys.exit(f"连不上 {BASE}，服务启动了吗？（{e}）")
status_h, health = call_json("GET", "/api/health")
check("未登录调用流式接口返回 401", status_h == 200 and status_401 == 401)

user = {"username": f"st_{random.randint(100000, 999999)}", "password": "secret123"}
call_json("POST", "/api/register", user)
call_json("POST", "/api/login", user)

evs, first_dt, total_dt = collect_stream({"questionId": 1, "message": "讲解 defer"})
if any(e.get("t") == "error" and "配置" in e.get("message", "") for e in evs):
    sys.exit("请按说明设置好 8090 假服务环境变量后再运行")
deltas = [e["text"] for e in evs if e.get("t") == "delta"]
check("流式增量分块到达（首段早于结束）", len(deltas) >= 2 and first_dt is not None and first_dt < total_dt - 0.15)

evs, _, _ = collect_stream({"message": "带思考标签"})
think = "".join(e["text"] for e in evs if e.get("t") == "think")
ans = "".join(e["text"] for e in evs if e.get("t") == "delta")
done_ev = next((e for e in evs if e.get("t") == "done"), {})
_, detail = call_json("GET", f"/api/chats/{done_ev.get('chatId')}")
saved = (detail.get("messages") or [{}])[-1].get("content", "")
check("跨分片的 <think>...</think> 正确拆分为 think 与 delta",
      think == "先理清作用域" and ans == "defer 在函数返回前执行。" and saved == "defer 在函数返回前执行。")

evs, _, _ = collect_stream({"message": "字段推理"})
think2 = "".join(e["text"] for e in evs if e.get("t") == "think")
ans2 = "".join(e["text"] for e in evs if e.get("t") == "delta")
check("reasoning_content 字段也能归类为 think 事件", think2 == "逐层排查" and ans2 == "检查响应头即可。")

resp = open_stream({"message": "慢速流"})
read_lines = 0
for _ in resp:
    read_lines += 1
    if read_lines >= 3:
        break
resp.close()
time.sleep(0.8)
check("前端断开连接后后端及时中止上游", state["slow_aborted"] or state["slow_chunks"] < 10)

evs, _, _ = collect_stream({"message": "主模型卡死"})
ans_fb = "".join(e["text"] for e in evs if e.get("t") == "delta")
done_fb = next((e for e in evs if e.get("t") == "done"), {})
rem_before = done_fb.get("remaining", -1)
check("主模型半路卡死时触发 reset 并降级到备用模型",
      any(e.get("t") == "reset" for e in evs) and done_fb.get("model") == "backup-model" and ans_fb == "已由备用模型回答")

evs_err, _, _ = collect_stream({"message": "全部失败"})
evs_after, _, _ = collect_stream({"message": "恢复正常"})
done_after = next((e for e in evs_after if e.get("t") == "done"), {})
check("全部模型失败时返回 error 事件并退回次数",
      any(e.get("t") == "error" for e in evs_err) and done_after.get("remaining") == rem_before - 1)

print(f"\\n通过 {passed} / 7")`,explain:[{at:'import http.cookiejar',to:'from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer',text:'全部使用 Python 标准库，并发线程用来启动本地假上游服务。'},{at:'BASE = sys.argv[1]',to:'passed = 0',text:'后端地址与状态记录：slow_chunks 统计慢速流实际发出了几片，用来确认后端有没有在前端断开后止损。'},{at:'class FakeStreamLLM(BaseHTTPRequestHandler):',to:'line = "data: "',text:'支持 HTTP/1.1 分块传输的假大模型服务，读取请求体的逻辑与前两关一致，并拼装 SSE data 行。'},{at:'raw = line.encode("utf-8")',to:'self.end_headers()',text:'按照 HTTP/1.1 chunked 编码实时刷出每一条 SSE data: 事件，保证 Go/Java/Node/Python 客户端都能逐片立刻读到。'},{at:'def reply_json(self, status, data):',to:'self.wfile.write(raw)',text:'用于返回 500 错误响应。'},{at:'def do_POST(self):',to:'return self.reply_json(500',text:'解析模型名与最后一句暗号，“全部失败”直接返回 500。'},{at:'self.start_sse()',to:'self.write_sse({"choices": [{"delta": {"content": "已由备用模型回答"}}]})',text:'遇到“主模型卡死”时，primary-model 先吐半截再故意睡 2 秒触发后端空闲超时，backup-model 则立刻回复完整答案。'},{at:'elif "慢速流" in last:',to:'time.sleep(0.15)',text:'慢速流循环吐 20 片，方便在读完 3 行后断连检查有没有半途停掉。'},{at:'elif "带思考标签" in last:',to:'self.write_sse({"choices": [{"delta": {"content": "检查响应头即可。"}}]})',text:'分别模拟跨分片切断的 <think>…</think> 标签，以及 reasoning_content 字段。'},{at:'else:',to:'state["slow_aborted"] = True',text:'正常情况每 0.25 秒吐一片，结束后发 [DONE] 和 chunked 终止块；捕获到 OSError 说明后端已关闭上游连接。'},{at:'def log_message(self, *args):',to:'threading.Thread(',text:'静默日志并在后台启动 8090 假服务。'},{at:'def check(name, ok):',to:'passed += bool(ok)',text:'打印单项验收结果。'},{at:'opener = urllib.request.build_opener(',to:'return e.code, json.loads(e.read().decode("utf-8") or "null")',text:'带 Cookie 罐的普通 JSON 请求方法。'},{at:'def open_stream(body):',to:'return opener.open(req, timeout=15)',text:'发起流式请求并返回响应流对象。'},{at:'def collect_stream(body):',to:'return events, first_dt, time.monotonic() - t0',text:'逐行读取 NDJSON 事件流，记录首段 delta 到达的时间和总耗时。'},{at:'try:',to:'check("未登录调用流式接口返回 401"',text:'第 1 项：未登录访问流式接口被拦截。'},{at:'user = {"username":',to:'call_json("POST", "/api/login", user)',text:'注册并登录测试账号。'},{at:'evs, first_dt, total_dt = collect_stream(',to:'check("流式增量分块到达（首段早于结束）"',text:'第 2 项：首段 delta 比整体完成早到达至少 0.15 秒，证明没有等整段生成完才一股脑返回。'},{at:'evs, _, _ = collect_stream({"message": "带思考标签"})',to:'and saved == "defer 在函数返回前执行。")',text:'第 3 项：验证被切碎的标签完美分离，而且历史记录里只存干净的正文。'},{at:'evs, _, _ = collect_stream({"message": "字段推理"})',to:'check("reasoning_content 字段也能归类为 think 事件"',text:'第 4 项：验证 reasoning_content 字段也走思考事件。'},{at:'resp = open_stream({"message": "慢速流"})',to:'check("前端断开连接后后端及时中止上游"',text:'第 5 项：读 3 行就关闭连接，确认假服务发的片数远小于 20 片。'},{at:'evs, _, _ = collect_stream({"message": "主模型卡死"})',to:'and ans_fb == "已由备用模型回答")',text:'第 6 项：主模型超时后流里出现 reset 并切到 backup-model 完成回答。'},{at:'evs_err, _, _ = collect_stream({"message": "全部失败"})',to:'print(f"\\n通过 {passed} / 7")',text:'第 7 项：全模型失败发 error 且退回次数（后面恢复正常时次数只少了 1），最后汇总输出。'}]},
  {title:'这一关学到了什么',body:'一、上游大模型通常用 SSE（data: {...}）推流，后端推给前端则常用按行切分的 NDJSON（application/x-ndjson），并加上 Cache-Control: no-store, no-transform 与 X-Accel-Buffering: no 防止网关攒包；\n二、网络分片随时会在标签中间断开，需要用三态解析器（init / think / answer）配合 </think> 前缀尾缓冲和 flush() 安全拆分，同时兼容 reasoning_content 字段，且只把干净正文存入对话历史；\n三、流式连接要配置首字超时、空闲看门狗和总时长硬截止，长等待时发 ping 心跳保活；\n四、主模型半路失败且已输出过内容时，先发 reset 清空前端残缺文本，再无缝切换到备用模型；全部失败时发 error 并退回次数；\n五、前端用 AbortController 随时停止生成，后端监听连接断开立刻中止上游计费请求；\n六、下一关预告（第 17 关：笔记本、自建题库与全站检索）：把 AI 老师的讲解和自己的笔记存进个人笔记本，支持按材料自动出题建库，并用统一检索串起全站题目、笔记与卡片。'}
 ],quiz:[
  {id:'pj-stream-1',q:'为什么后端向前端推流常选 NDJSON 而不是浏览器原生的 EventSource（SSE）？',options:['EventSource 能自动重连但传输速度慢得多','EventSource 只支持 GET，不便携带 JSON 正文','浏览器禁止同一域名同时存在多个 SSE 连接','SSE 协议规范本身不支持 UTF-8 中文编码'],why:['传输速率一样，都是基于 HTTP 长连接逐块发送字节。','','HTTP/2 下不存在这个问题，HTTP/1.1 下是全局 6 连接限制而非 SSE 独有。','SSE 标准规定正文本身就是 UTF-8 编码，完全支持中文。'],answer:1,explain:'原生 EventSource 只能发 GET 请求，而且不能自定义请求头或携带对话历史的 JSON 请求体。用 fetch 加 ReadableStream 配合按行解析的 NDJSON，既能 POST 对话上下文，客户端解析也只需按换行切分。'},
  {id:'pj-stream-2',q:'在流式回答里设置 Cache-Control: no-transform 和 X-Accel-Buffering: no 的作用是？',options:['让浏览器把流式响应存进本地磁盘缓存，刷新后无需重连','通知上游大模型服务提高采样温度并加快首字输出速度','禁止反向代理压缩或攒满整包，确保每个分片立刻送达','强制客户端在断线后把没收完的事件重新请求一遍并合并'],why:['no-store 和 no-transform 是禁用缓存和中间变换，恰恰不缓存。','这两个是发给代理和浏览器的响应头，不会传给上游模型。','','它们只控制中间代理不要缓冲数据，不负责客户端断线重连。'],answer:2,explain:'Nginx 等反向代理和 gzip 压缩中间件默认会等缓冲区攒满再一起发给客户端，导致前端看到“卡住十秒然后整段蹦出”。加上这两个响应头后，每写一行就能立刻刷新送到浏览器。'},
  {id:'pj-stream-3',q:'主模型已经向前端吐了半截内容后才触发空闲超时，后端切换到备用模型前应该先做什么？',options:['直接把备用模型的输出接在后面继续往流里写','先关闭当前 HTTP 连接，让浏览器自动重发请求','先把刚才那半截残缺内容存进 chat_messages 表','先发送一行 reset 事件通知前端清空残缺内容'],why:['直接拼接会把两个模型各说一半的话混在一起，逻辑错乱。','流式响应已返回 200 状态码，断开连接只会让前端误以为中断或报错。','半截失败输出不应该污染多轮对话历史，否则下次追问上下文就乱了。',''],answer:3,explain:'主模型已经写出一部分数据时，前端屏幕上已经显示了半截话。切换备用模型前必须先推一条 {"t":"reset"} 让前端清空当前正在生成的思考和正文，再重新流式输出备用模型的完整回答。'},
  {id:'pj-stream-4',type:'multi',q:'关于流式对话的三段式超时控制，下面说法正确的有？（多选）',options:['首字超时能发现迟迟不吐第一个字的假死连接','空闲看门狗每次收到增量分片都会重置计时器','总时长超时为整次流式请求设置最终硬截止点','前端用了 AbortController 后服务端就不需设超时'],why:['','','','前端可能直接关掉网页或网络异常静默断开，服务端必须自己用三段超时保护连接池和上游预算。'],answers:[0,1,2],explain:'首字超时防冷启动卡住，空闲看门狗防半路断流卡死，总时长截止防慢流长期占资源；前端的 AbortController 只负责用户主动中断，服务端自身仍需独立保护。'},
  {id:'pj-stream-5',type:'multi',q:'解析 <think>...</think> 流式分片时，哪些做法能避免跨分片截断和错漏？（多选）',options:['只要当前分片不含 </think> 就直接把整块当作正文输出','刚开流时若缓冲还是 <think> 的前缀就先暂存等下一片','把思考内容和正文拼在同一条 assistant 消息里入库','思考阶段只保留末尾可能构成 </think> 前缀的小段尾巴'],why:['模型在吐 </think> 前的分片全都不含结束标签，直接当正文输出会把思考草稿全漏给用户。','','思考草稿写进历史会白白消耗后续多轮对话的 token 并干扰模型推理，应该只存正式正文。',''],answers:[1,3],explain:'开流阶段需要识别被切碎的 <think>，思考阶段需要按 </think> 的前缀保留尾部缓冲并把前面的思考立刻吐出；流结束后只把干净的正文存进数据库。'},
  {id:'pj-stream-6',type:'judge',q:'流式接口一开始返回 HTTP 200 并推送了几行数据，如果后面所有备用模型都失败了，应该把 HTTP 状态码改成 502。',answer:false,explain:'错误。HTTP 状态码在写出第一行响应体前就已经发给浏览器了，流开始后无法改回 502。此时只能在 NDJSON 流里发送 {"t":"error","message":"..."} 事件通知前端，并把刚才扣掉的提问次数退回。'},
  {id:'pj-stream-7',type:'judge',q:'当用户点击“停止生成”且模型还没有输出任何思考或正文时，后端感知连接断开后应该把刚才占用的提问次数退回。',answer:true,explain:'正确。用户还没看到任何有效回答就主动取消（或者首字还没回来），这次取消不应算作一次有效答疑；只有真正开始输出内容或完成生成才保留扣费记录，同时要立刻取消上游请求避免继续产生模型费用。'},
  {id:'pj-stream-8',type:'fill',q:'在支持思考折叠的前端界面中，为了在用户点击“停止生成”时立刻中止正在读取的 fetch 请求和流，浏览器标准 API 是 ＿＿＿＿＿＿＿＿。',accepted:['AbortController','abortcontroller'],explain:'AbortController。把它的 signal 传给 fetch(url, { signal })，点击停止按钮时调用 controller.abort() 即可立刻关闭连接并终止 ReadableStream 读取。'},
  {id:'pj-stream-9',type:'short',q:'为什么不能简单地在每个网络分片里用 chunk.includes("<think>") 和 chunk.includes("</think>") 来分离思考过程和正式回答？请说明至少两个具体故障场景并给出流式解析器的解决思路。',reference:'一、跨分片截断：TCP 或 SSE 分片可能在标签中间断开（例如上一片结尾是 "<thi" 或 "</th"，下一片开头是 "nk>" 或 "ink>"），直接 includes 会漏识别，还可能把半截标签当成正文展示给用户。\n二、状态丢失：标签成对出现，跨分片时必须记住当前处于“等待开头”“思考中”还是“正文中”，否则 </think> 出现之前的纯文本思考块会被误判为正式回答。\n解决思路：维护 init / think / answer 状态机和尾部缓冲区。init 阶段暂存可能是 <think> 前缀的字符；think 阶段查找 </think>，未找到时只留末尾可能是 </think> 前缀的小段尾巴在缓冲区，把前面已确认的思考文本立刻吐出，流结束时调用 flush 清空余下缓冲。',points:['指出跨分片导致标签被拆开（如 <thi + nk> 或 </th + ink>）而漏判的问题','指出单块判断缺乏状态机记忆，会把思考阶段的普通文本误当正文或泄露出半截标签','说明基于状态机与尾部前缀缓冲（及流结束 flush）的流式处理方案'],explain:'核心考的是字节流没有应用层消息边界这一网络常识：必须通过状态机加最小前缀回退缓冲，既不漏判跨片标签，又能低延迟吐出已确认的文本。'},
  {id:'pj-stream-code-1',type:'code',q:'请实现一个分片安全的 <think>...</think> 流式解析器 ThinkSplitter，包含 feedChunk(chunk) 和 flush() 两个方法。要求能正确处理跨分片被切开的 <think> 与 </think> 标签，分别回调 onThink(text) 和 onAnswer(text)；若开头不是 <think>，则直接作为正式回答透传。',reference:'class ThinkSplitter:\n    def __init__(self, on_think, on_answer):\n        self.mode = "init"\n        self.buf = ""\n        self.on_think = on_think\n        self.on_answer = on_answer\n\n    def feed_chunk(self, chunk: str) -> None:\n        if not chunk:\n            return\n        if self.mode == "answer":\n            self.on_answer(chunk)\n            return\n        self.buf += chunk\n        if self.mode == "init":\n            trimmed = self.buf.lstrip()\n            if not trimmed:\n                return\n            if trimmed.startswith("<think>"):\n                self.buf = trimmed[len("<think>"):]\n                self.mode = "think"\n            elif "<think>".startswith(trimmed):\n                return\n            else:\n                self.mode = "answer"\n                self.on_answer(self.buf)\n                self.buf = ""\n                return\n        while self.mode == "think":\n            close_idx = self.buf.find("</think>")\n            if close_idx >= 0:\n                if close_idx > 0:\n                    self.on_think(self.buf[:close_idx])\n                rest = self.buf[close_idx + len("</think>"):]\n                self.buf = ""\n                self.mode = "answer"\n                if rest:\n                    self.on_answer(rest)\n                return\n            last_lt = self.buf.rfind("<")\n            if last_lt >= 0 and "</think>".startswith(self.buf[last_lt:]):\n                if last_lt > 0:\n                    self.on_think(self.buf[:last_lt])\n                self.buf = self.buf[last_lt:]\n                return\n            if self.buf:\n                self.on_think(self.buf)\n                self.buf = ""\n            return\n\n    def flush(self) -> None:\n        if not self.buf:\n            return\n        if self.mode == "think":\n            self.on_think(self.buf)\n        else:\n            self.on_answer(self.buf)\n        self.buf = ""',points:['TODO 1：init 阶段跳过开头空白后判断是否为 <think> 前缀，匹配完整 <think> 则切入 think，确定非标签则直接进入 answer 并吐出缓冲','TODO 2：think 阶段查找 </think>；若找到则吐出前半段思考并切到 answer；未找到时仅保留末尾可能是 </think> 前缀的尾巴，将前面已确认的思考立刻吐出','TODO 3：answer 阶段直接透传分片；flush() 在流结束时把缓冲区残余文本按当前状态回调并清空'],explain:'在 init 与 think 阶段只缓冲“可能是标签前缀”的最短尾巴，既能防止 <thi + nk> 或 </th + ink> 泄露，又不会把整段回答攒完才输出。'},
  {id:'pj-stream-go-1',stack:'go',q:'Go 的流式接口每写完一行 NDJSON 事件，为什么要用 http.NewResponseController(w).Flush()？',options:['让 Go 把多行 NDJSON 自动压缩后再发','把当前 HTTP 连接升级成双向 WebSocket','立刻把响应缓冲区推给客户端防止攒包','等待下游读完后再提交并关闭当前事务'],why:['Flush 是立刻冲刷缓冲区，刚好和攒起来压缩相反。','NDJSON 依然是普通 HTTP 响应，并没有升级成 WebSocket。','','Flush 只操作 HTTP 响应缓冲，和数据库事务生命周期无关。'],answer:2,explain:'Go 的 net/http 默认会先在内存缓冲写响应直到一定大小或函数返回才发包。每次写完一行事件调用 Flush()，浏览器才能实时收到增量数据。'},
  {id:'pj-stream-java-1',stack:'java',q:'Java Spring Boot 里使用 StreamingResponseBody 返回流式数据时，向 OutputStream 写入失败抛出 IOException 通常意味着什么？',options:['客户端已主动断开，应停流并关闭上游输入流','Jackson 序列化 JSON 失败，需要重试当前事件','SQLite 数据库连接池已满，应回滚当前事务','Spring 要求把状态码改成 502 再重新推流'],why:['','write 和 flush 写入字节时抛 IOException 通常是底层 socket 断开（Broken pipe），不是 JSON 格式问题。','写 HTTP 输出流不直接操作 SQLite 连接池。','开始流式写出后响应头早已发出，无法再改状态码。'],answer:0,explain:'当用户在前端点击“停止生成”或关闭标签页时，TCP 连接断开，服务端下一次 flush 就会触发 IOException。捕获它后应立刻关闭上游大模型 InputStream，及时止损。'},
  {id:'pj-stream-node-1',stack:'node',q:'Express 流式接口中，为什么用 res.on("close", …) 配合 !res.writableEnded 来监听客户端中途断开，而不是只看 req.on("close")？',options:['req 对象上没有 close 事件，调用它会直接报错','请求体读完时 req 就可能触发 close，不代表客户端断开了','res.on("close") 会自动中止上游 fetch 而无需控制器','writableEnded 为 true 才说明用户中途点击了停止按钮'],why:['IncomingMessage 有 close 事件，只是语义容易和请求体消费完成混淆。','','仍需要在回调里手动调用 AbortController.abort() 去取消上游 fetch。','正常流结束时 writableEnded 为 true；中途异常或中止断开时它才为 false。'],answer:1,explain:'POST 请求的 JSON 请求体一读完，req 就可能结束并触发事件；监听响应对象 res 的 close 并检查 !res.writableEnded，才能准确判断响应还没写完客户端就主动断开了。'},
  {id:'pj-stream-python-1',stack:'python',q:'FastAPI 流式接口里，使用 async with httpx.AsyncClient() 配合 StreamingResponse 的异步生成器有什么优势？',options:['能让 SQLite 的同步查询自动变成并行执行','可以把多条 NDJSON 事件自动打包成一条返回','客户端断开后上游还会继续生成并补写完整历史','客户端断开时生成任务被取消，可立即关闭上游连接'],why:['httpx 只管 HTTP 请求，不改变 sqlite3 的同步模型。','流式传输恰恰要求逐条尽早发送，而不是打包延迟。','客户端中断后应该立刻止损取消上游，而不是继续白花 token。',''],answer:3,explain:'Starlette/FastAPI 会在客户端断开时取消异步生成器任务；配合 async with 的上下文退出机制，底层 httpx 上游流也会立刻关闭，不浪费模型额度。'}
 ]};
